window.LPTV_QUESTIONS=[{"id":"CARS1.2","category":"Alertness","question":"Before making a U-turn in the road you should always:","question_it":"Prima di effettuare un'inversione a U sulla strada devi sempre:","answers":["Select a higher gear than normal","Signal so that other drivers can slow down","Look over your shoulder for final confirmation","Give another signal as well as using your indicators"],"answers_it":["Selezionare una marcia più alta del normale","Segnalare affinché gli altri conducenti rallentino","Guardare sopra la spalla per una conferma finale","Fare un altro segnale oltre agli indicatori"],"correct":[2],"explanation":"A final shoulder check helps reveal vehicles or cyclists in the blind spot.","explanation_it":"Il controllo finale sopra la spalla permette di vedere veicoli o ciclisti nell'angolo cieco.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS1.3","category":"Alertness","question":"As a driver, what do you understand by the term 'blind spot'?","question_it":"Come conducente, cosa intendi per 'angolo cieco'?","answers":["An area covered by your left-hand mirror","An area not covered by your headlights","An area covered by your right-hand mirror","An area not covered by your mirrors"],"answers_it":["Un'area coperta dallo specchio sinistro","Un'area non illuminata dai fari","Un'area coperta dallo specchio destro","Un'area non coperta dagli specchi"],"correct":[3],"explanation":"A blind spot is an area around the vehicle that cannot be seen in the mirrors.","explanation_it":"L'angolo cieco è un'area attorno al veicolo che non è visibile negli specchi.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS1.7","category":"Alertness","question":"What does the abbreviation MSM mean?","question_it":"Cosa significa l'abbreviazione MSM?","answers":["Mirror, signal, manoeuvre","Manoeuvre, speed, mirror","Mirror, speed, manoeuvre","Manoeuvre, signal, mirror"],"answers_it":["Specchio, segnale, manovra","Manovra, velocità, specchio","Specchio, velocità, manovra","Manovra, segnale, specchio"],"correct":[0],"explanation":"MSM is the standard Mirror–Signal–Manoeuvre routine.","explanation_it":"MSM è la sequenza standard Specchio–Segnale–Manovra.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS1.9","category":"Alertness","question":"When following a large vehicle you should stay well back because:","question_it":"Quando segui un veicolo grande devi mantenerti ben distante perché:","answers":["It helps you keep out of the wind","It helps the large vehicle stop more easily","It allows the driver to see you in the mirror","It allows you to corner more quickly"],"answers_it":["Ti protegge dal vento","Aiuta il veicolo grande a fermarsi più facilmente","Permette al conducente di vederti nello specchio","Ti permette di affrontare le curve più velocemente"],"correct":[2],"explanation":"Staying back keeps you visible in the large vehicle driver's mirrors and improves your view ahead.","explanation_it":"Mantenersi distanti ti rende visibile negli specchi del conducente e migliora la visuale davanti.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS1.10","category":"Alertness","question":"In which situation should you avoid overtaking?","question_it":"In quale situazione devi evitare il sorpasso?","answers":["On a 50 kph road","In a one-way street","Just after a bend","Approaching a dip in the road"],"answers_it":["Su una strada con limite di 50 km/h","In una strada a senso unico","Subito dopo una curva","Avvicinandoti a un avvallamento"],"correct":[3],"explanation":"A dip can hide oncoming traffic, so overtaking is unsafe.","explanation_it":"Un avvallamento può nascondere il traffico in arrivo, quindi il sorpasso è pericoloso.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS1.12","category":"Alertness","question":"Why should you not use a mobile phone while driving?","question_it":"Perché non devi usare il telefono mentre guidi?","answers":["Reception is poor when the engine is running","You can drive safely with one hand","It might distract your attention from the road ahead","It is allowed when no traffic is near"],"answers_it":["La ricezione è scarsa con il motore acceso","Puoi guidare in sicurezza con una mano","Può distrarre la tua attenzione dalla strada","È permesso quando non c'è traffico vicino"],"correct":[2],"explanation":"Phone use can distract your attention and reduce control of the vehicle.","explanation_it":"L'uso del telefono può distrarti e ridurre il controllo del veicolo.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS1.13","category":"Alertness","question":"Using a hands-free phone while driving:","question_it":"Usare un telefono vivavoce durante la guida:","answers":["Is very good for road safety","Could distract your attention from the road","Is recommended by the Road Code","Is safe as long as you slow down"],"answers_it":["È molto positivo per la sicurezza","Può distrarre la tua attenzione dalla strada","È raccomandato dal Codice della strada","È sicuro se rallenti"],"correct":[1],"explanation":"Hands-free use still creates mental distraction.","explanation_it":"Anche il vivavoce crea distrazione mentale.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS1.18","category":"Vulnerable road users","question":"On a narrow country road, how should you pass a cyclist?","question_it":"Su una stretta strada di campagna, come devi sorpassare un ciclista?","answers":["Quickly, sounding the horn","Quickly, leaving plenty of room","Slowly, leaving plenty of room","Slowly, sounding the horn"],"answers_it":["Velocemente, suonando il clacson","Velocemente, lasciando molto spazio","Lentamente, lasciando molto spazio","Lentamente, suonando il clacson"],"correct":[2],"explanation":"Pass slowly and leave plenty of room because cyclists may wobble or swerve.","explanation_it":"Passa lentamente e lascia molto spazio perché il ciclista può oscillare o deviare.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS1.24","category":"Alertness","question":"You are driving in the dark and are dazzled by oncoming headlights. What should you do?","question_it":"Guidi al buio e vieni abbagliato dai fari di un veicolo in arrivo. Cosa devi fare?","answers":["Slow down or stop","Pull down the sun visor","Flash your headlights","Close your eyes"],"answers_it":["Rallentare o fermarti","Abbassare l'aletta parasole","Lampeggiare con i fari","Chiudere gli occhi"],"correct":[0],"explanation":"Reduce speed and stop if necessary until you can see clearly again.","explanation_it":"Riduci la velocità e fermati se necessario finché non recuperi una buona visibilità.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS1.25","category":"Alertness","question":"You are driving at dusk. When should your lights be switched on? Select 2 answers.","question_it":"Stai guidando al crepuscolo. Quando devono essere accese le luci? Seleziona 2 risposte.","answers":["So that others can see you","Even when street lights are lit","Only when street lights are lit","Only when others have done so"],"answers_it":["Affinché gli altri possano vederti","Anche quando l'illuminazione stradale è accesa","Solo quando l'illuminazione stradale è accesa","Solo quando lo fanno gli altri"],"correct":[0,1],"explanation":"At dusk, use lights to make yourself visible, even on lit streets.","explanation_it":"Al crepuscolo usa le luci per renderti visibile, anche su strade illuminate.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS2.4","category":"Pedestrian crossings","question":"You are approaching a zebra crossing. Pedestrians are waiting to cross. You should:","question_it":"Ti avvicini a un attraversamento pedonale e ci sono pedoni in attesa. Devi:","answers":["Wave them across","Slow down and prepare to stop","Flash your headlights","Give way only to elderly people"],"answers_it":["Fare cenno di attraversare","Rallentare e prepararti a fermarti","Lampeggiare con i fari","Dare precedenza solo agli anziani"],"correct":[1],"explanation":"Approach slowly and be ready to stop for pedestrians.","explanation_it":"Avvicinati lentamente e preparati a fermarti per i pedoni.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS2.6","category":"Pedestrian crossings","question":"Why should you never wave or urge people across at a pedestrian crossing?","question_it":"Perché non devi mai invitare con un gesto le persone ad attraversare?","answers":["There may be another vehicle coming","They may not be ready","It is safer for you to carry on","They may not be looking"],"answers_it":["Potrebbe arrivare un altro veicolo","Potrebbero non essere pronti","È più sicuro proseguire","Potrebbero non guardare"],"correct":[0],"explanation":"Another vehicle may approach from a direction the pedestrian cannot see.","explanation_it":"Un altro veicolo potrebbe arrivare da una direzione che il pedone non vede.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS2.9","category":"Safety margins","question":"When may you use the two-second rule?","question_it":"Quando puoi usare la regola dei due secondi?","answers":["When emerging on wet roads","To keep a safe gap from the vehicle in front","Before using the MSM routine","Before restarting a stalled engine"],"answers_it":["Quando ti immetti su strade bagnate","Per mantenere una distanza di sicurezza dal veicolo davanti","Prima della sequenza MSM","Prima di riavviare un motore spento"],"correct":[1],"explanation":"The two-second rule measures a safe following gap in good conditions.","explanation_it":"La regola dei due secondi misura una distanza sicura in condizioni normali.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS2.14","category":"Safety margins","question":"Why is following a large vehicle too closely unwise? Select 2 answers.","question_it":"Perché è imprudente seguire troppo da vicino un veicolo grande? Seleziona 2 risposte.","answers":["Your engine will overheat","Your view ahead is reduced","Your brakes will overheat","The driver cannot see you in the mirrors"],"answers_it":["Il motore si surriscalda","La visuale davanti è ridotta","I freni si surriscaldano","Il conducente non può vederti negli specchi"],"correct":[1,3],"explanation":"You lose forward vision and may sit in the large vehicle's blind spot.","explanation_it":"Perdi visuale davanti e potresti trovarti nell'angolo cieco del veicolo grande.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS2.17","category":"Safety margins","question":"On a wet and slippery road, what minimum time gap should you leave?","question_it":"Su una strada bagnata e scivolosa, quale intervallo minimo devi lasciare?","answers":["Three seconds","Two seconds","One second","Four seconds"],"answers_it":["Tre secondi","Due secondi","Un secondo","Quattro secondi"],"correct":[3],"explanation":"In wet conditions, double the normal two-second gap to at least four seconds.","explanation_it":"Sul bagnato raddoppia i due secondi normali, lasciandone almeno quattro.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS2.19","category":"Attitude","question":"The driver behind is following very closely. What should you do?","question_it":"Il conducente dietro ti segue troppo da vicino. Cosa devi fare?","answers":["Move near the centre line","Slow down gradually and increase the gap ahead","Wave the driver past","Ignore the driver"],"answers_it":["Spostarti vicino alla linea centrale","Rallentare gradualmente e aumentare lo spazio davanti","Fare cenno al conducente di sorpassare","Ignorarlo"],"correct":[1],"explanation":"Increasing the space ahead gives you more room to brake smoothly.","explanation_it":"Aumentare lo spazio davanti ti consente di frenare più dolcemente.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS2.20","category":"Attitude","question":"You are driving at the legal speed limit. A vehicle comes up quickly behind flashing its headlights. You should:","question_it":"Guidi al limite legale e un veicolo si avvicina rapidamente lampeggiando. Devi:","answers":["Prevent it from overtaking","Touch the brakes","Accelerate","Allow the vehicle to overtake"],"answers_it":["Impedire il sorpasso","Toccare i freni","Accelerare","Lasciare che il veicolo sorpassi"],"correct":[3],"explanation":"Do not compete or obstruct; allow it to pass when safe.","explanation_it":"Non competere e non ostacolare; lascia passare il veicolo quando è sicuro.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS2.22","category":"Attitude","question":"When are you permitted to exceed the maximum speed limit?","question_it":"Quando è consentito superare il limite massimo di velocità?","answers":["When the road is clear","At no time","When overtaking","Between midnight and 6 am"],"answers_it":["Quando la strada è libera","Mai","Durante un sorpasso","Tra mezzanotte e le 6"],"correct":[1],"explanation":"The maximum speed limit must not be exceeded.","explanation_it":"Il limite massimo di velocità non deve essere superato.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS2.30","category":"Emergency vehicles","question":"Which vehicles may use blue flashing beacons? Select 2 answers.","question_it":"Quali veicoli possono usare lampeggianti blu? Seleziona 2 risposte.","answers":["Doctor on call","Police patrol","Ambulance","Breakdown recovery","Road maintenance"],"answers_it":["Medico reperibile","Pattuglia di polizia","Ambulanza","Soccorso stradale","Manutenzione stradale"],"correct":[1,2],"explanation":"Police and ambulances use blue flashing beacons for emergency response.","explanation_it":"Polizia e ambulanze usano lampeggianti blu per interventi d'emergenza.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS2.31","category":"Emergency vehicles","question":"An ambulance with a flashing blue light is following you. What should you do?","question_it":"Un'ambulanza con lampeggiante blu ti segue. Cosa devi fare?","answers":["Pull over as soon as safely possible","Brake harshly in the road","Maintain speed and course","Accelerate away"],"answers_it":["Accostare appena è possibile in sicurezza","Frenare bruscamente in strada","Mantenere velocità e direzione","Accelerare"],"correct":[0],"explanation":"Make way promptly but safely; do not create another hazard.","explanation_it":"Lascia strada rapidamente ma in sicurezza, senza creare un altro pericolo.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS2.32","category":"Buses","question":"A bus at a stop is signalling right. What should you do?","question_it":"Un autobus fermo segnala a destra. Cosa devi fare?","answers":["Slow down and sound your horn","Slow down and give way if safe","Sound the horn and continue","Flash headlights and slow down"],"answers_it":["Rallentare e suonare il clacson","Rallentare e dare precedenza se è sicuro","Suonare il clacson e proseguire","Lampeggiare e rallentare"],"correct":[1],"explanation":"Give the bus room to move out when it is safe to do so.","explanation_it":"Lascia spazio all'autobus per ripartire quando è sicuro.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS2.34","category":"Horn","question":"Why should you use your horn?","question_it":"Perché devi usare il clacson?","answers":["To alert others of your presence","To signal annoyance","To greet other road users","To obtain right of way"],"answers_it":["Per avvertire gli altri della tua presenza","Per mostrare fastidio","Per salutare","Per ottenere la precedenza"],"correct":[0],"explanation":"The horn is a warning device, not a way to complain or claim priority.","explanation_it":"Il clacson è un dispositivo di avvertimento, non serve per protestare o pretendere precedenza.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS3.4","category":"Vehicle safety","question":"Which TWO are adversely affected if tyres are under-inflated?","question_it":"Quali DUE elementi sono influenzati negativamente da pneumatici sgonfi?","answers":["Steering","Braking","Parking","Changing gear"],"answers_it":["Sterzo","Frenata","Parcheggio","Cambio marcia"],"correct":[0,1],"explanation":"Low tyre pressure impairs steering response and braking performance.","explanation_it":"La bassa pressione peggiora la risposta dello sterzo e la frenata.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS3.8","category":"Vehicle safety","question":"How often should tyre pressures be checked at least?","question_it":"Con quale frequenza minima va controllata la pressione degli pneumatici?","answers":["At every VRT test","Once a week","Once a month","At every service"],"answers_it":["A ogni VRT","Una volta alla settimana","Una volta al mese","A ogni tagliando"],"correct":[1],"explanation":"Regular weekly checks help maintain safety and fuel efficiency.","explanation_it":"Il controllo settimanale aiuta a mantenere sicurezza ed efficienza.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS3.18","category":"Vehicle lighting","question":"When must you use dipped headlights during the day?","question_it":"Quando devi usare gli anabbaglianti durante il giorno?","answers":["When parking","Along narrow streets","In poor visibility","All the time"],"answers_it":["Durante il parcheggio","Nelle strade strette","Con scarsa visibilità","Sempre"],"correct":[2],"explanation":"Dipped headlights make you visible without dazzling others in poor visibility.","explanation_it":"Gli anabbaglianti ti rendono visibile senza abbagliare in condizioni di scarsa visibilità.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS3.23","category":"Eco driving","question":"How can a driver help the environment? Select 3 answers.","question_it":"Come può un conducente aiutare l'ambiente? Seleziona 3 risposte.","answers":["Service the vehicle properly","Use gentle acceleration","Use harsh acceleration","Drive faster","Reduce speed","Use leaded fuel"],"answers_it":["Fare corretta manutenzione","Accelerare dolcemente","Accelerare bruscamente","Guidare più velocemente","Ridurre la velocità","Usare benzina con piombo"],"correct":[0,1,4],"explanation":"Good maintenance, gentle acceleration and lower speed reduce fuel use and emissions.","explanation_it":"Buona manutenzione, accelerazione dolce e velocità ridotta diminuiscono consumi ed emissioni.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS3.27","category":"Environment","question":"Motor vehicles can harm the environment resulting in: Select 3 answers.","question_it":"I veicoli possono danneggiare l'ambiente causando: Seleziona 3 risposte.","answers":["Using up natural resources","Damage to buildings","Less use of electric vehicles","Improved public transport","Reduced health risks","Air pollution"],"answers_it":["Consumo di risorse naturali","Danni agli edifici","Minore uso di veicoli elettrici","Migliore trasporto pubblico","Riduzione dei rischi sanitari","Inquinamento atmosferico"],"correct":[0,1,5],"explanation":"Road transport consumes resources, contributes to air pollution and can damage buildings.","explanation_it":"Il trasporto stradale consuma risorse, inquina l'aria e può danneggiare gli edifici.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS3.28","category":"Eco driving","question":"To reduce environmental damage caused by your vehicle, what should you do? Select 3 answers.","question_it":"Per ridurre il danno ambientale causato dal veicolo, cosa devi fare? Seleziona 3 risposte.","answers":["Use busy routes","Plan well ahead","Brake in good time","Avoid harsh acceleration","Use narrow side streets"],"answers_it":["Usare percorsi trafficati","Pianificare in anticipo","Frenare per tempo","Evitare accelerazioni brusche","Usare strade laterali strette"],"correct":[1,2,3],"explanation":"Smooth, planned driving reduces fuel consumption and emissions.","explanation_it":"Una guida fluida e pianificata riduce consumi ed emissioni.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS3.38","category":"Horn","question":"When must you not sound your horn in a built-up area?","question_it":"Quando non devi suonare il clacson in una zona abitata?","answers":["Between 11:30 pm and 7:00 am","At any time","Between 10:00 pm and 6:00 am","Between 11:00 pm and 6:00 am"],"answers_it":["Tra le 23:30 e le 07:00","Sempre","Tra le 22:00 e le 06:00","Tra le 23:00 e le 06:00"],"correct":[3],"explanation":"The current question bank states that the horn must not be used in a built-up area between 11 pm and 6 am, except where necessary to avoid danger.","explanation_it":"La banca domande indica il divieto in zona abitata tra le 23:00 e le 06:00, salvo necessità per evitare un pericolo.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS4.7","category":"Fog","question":"When driving in fog, which measures are correct? Select 3 answers.","question_it":"Guidando nella nebbia, quali misure sono corrette? Seleziona 3 risposte.","answers":["Use sidelights only","Use dipped headlights","Keep close to the car in front","Slow down","Use full beam","Allow more time for the journey"],"answers_it":["Usare solo luci di posizione","Usare gli anabbaglianti","Stare vicino al veicolo davanti","Rallentare","Usare gli abbaglianti","Prevedere più tempo per il viaggio"],"correct":[1,3,5],"explanation":"Use dipped headlights, reduce speed and allow extra time in fog.","explanation_it":"Usa gli anabbaglianti, rallenta e prevedi più tempo nella nebbia.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS4.14","category":"Wet weather","question":"In heavy rain your steering suddenly becomes very light. What should you do?","question_it":"Con pioggia intensa lo sterzo diventa improvvisamente molto leggero. Cosa devi fare?","answers":["Brake firmly","Accelerate gently","Steer to the side","Ease off the accelerator"],"answers_it":["Frenare con decisione","Accelerare dolcemente","Sterzare verso il lato","Rilasciare l'acceleratore"],"correct":[3],"explanation":"Light steering may indicate aquaplaning; ease off the accelerator smoothly.","explanation_it":"Lo sterzo leggero può indicare aquaplaning; rilascia dolcemente l'acceleratore.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS4.20","category":"Junctions","question":"At a junction with limited visibility, what should you do?","question_it":"A un incrocio con visibilità limitata, cosa devi fare?","answers":["Be ready to move off quickly","Creep forward looking left","Creep forward looking right","Creep forward looking both ways"],"answers_it":["Prepararti a partire velocemente","Avanzare lentamente guardando a sinistra","Avanzare lentamente guardando a destra","Avanzare lentamente guardando in entrambe le direzioni"],"correct":[3],"explanation":"Creep forward carefully while checking both directions.","explanation_it":"Avanza lentamente e con cautela controllando entrambe le direzioni.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS4.30","category":"Overtaking","question":"When should you not overtake? Select 3 answers.","question_it":"Quando non devi sorpassare? Seleziona 3 risposte.","answers":["Driving up a long hill","In a one-way street","When the view ahead is blocked","Approaching a junction","Intending to turn left shortly afterwards"],"answers_it":["Salendo una lunga collina","In una strada a senso unico","Quando la visuale davanti è ostruita","Avvicinandoti a un incrocio","Quando devi girare a sinistra poco dopo"],"correct":[2,3,4],"explanation":"Do not overtake without a clear view, near junctions or before turning left.","explanation_it":"Non sorpassare senza visuale libera, vicino agli incroci o prima di svoltare a sinistra.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS5.6","category":"Alcohol","question":"Which THREE result from drinking alcohol and driving?","question_it":"Quali TRE conseguenze derivano dal bere alcol e guidare?","answers":["Less control","Poor judgement of speed","Greater awareness of danger","Faster reactions","A false sense of confidence"],"answers_it":["Minore controllo","Scarsa valutazione della velocità","Maggiore percezione del pericolo","Reazioni più rapide","Falso senso di sicurezza"],"correct":[0,1,4],"explanation":"Alcohol reduces control and judgement and creates false confidence.","explanation_it":"L'alcol riduce controllo e giudizio e crea una falsa sicurezza.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS5.10","category":"Concentration","question":"What can seriously affect concentration when driving besides alcohol? Select 3 answers.","question_it":"Cosa può compromettere seriamente la concentrazione oltre all'alcol? Seleziona 3 risposte.","answers":["Loud music","Tiredness","Contact lenses","Tinted windows","Drugs"],"answers_it":["Musica alta","Stanchezza","Lenti a contatto","Vetri oscurati","Droghe"],"correct":[0,1,4],"explanation":"Loud music, tiredness and drugs can seriously reduce concentration.","explanation_it":"Musica alta, stanchezza e droghe possono ridurre seriamente la concentrazione.","source":"Transport Malta Cars v4","status":"verified"},{"id":"CARS1.14","category":"Alertness","question":"Using a hands-free phone is likely to:","question_it":"L'uso di un telefono vivavoce può:","answers":["Reduce your view","Increase your concentration","Improve your safety","Divert your attention"],"answers_it":["Ridurre la visuale","Aumentare la concentrazione","Migliorare la sicurezza","Distogliere la tua attenzione"],"correct":[3],"explanation":"A hands-free conversation can still distract your mind from driving.","explanation_it":"Anche una conversazione in vivavoce può distrarre la mente dalla guida.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS1.15","category":"Alertness","question":"Using a mobile phone while you are driving:","question_it":"Usare il telefono cellulare mentre guidi:","answers":["Will affect your vehicle","Will reduce your field of vision","Could distract your attention from the road","Is acceptable in a vehicle with power steering"],"answers_it":["Danneggerà il veicolo","Ridurrà il campo visivo","Può distrarre la tua attenzione dalla strada","È accettabile in un veicolo con servosterzo"],"correct":[2],"explanation":"Mobile-phone use can take your attention away from the road.","explanation_it":"L'uso del telefono può distogliere la tua attenzione dalla strada.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS1.19","category":"Alertness","question":"To answer your mobile phone when driving you should:","question_it":"Per rispondere al telefono mentre guidi devi:","answers":["Slow down and allow others to overtake","Stop in a proper and convenient place","Keep the call time to a minimum","Reduce your speed wherever you are"],"answers_it":["Rallentare e lasciare sorpassare gli altri","Fermarti in un luogo adatto e sicuro","Mantenere breve la chiamata","Ridurre la velocità ovunque ti trovi"],"correct":[1],"explanation":"Stop safely before answering or making a call.","explanation_it":"Fermati in sicurezza prima di rispondere o telefonare.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS1.23","category":"Alertness","question":"Why should you be parked before using a mobile phone?","question_it":"Perché devi essere parcheggiato prima di usare il telefono?","answers":["Because the car electrics will be affected","So that control of your vehicle is not affected","So that a proper conversation can be held","Because reception is better when stopped"],"answers_it":["Perché l'impianto elettrico dell'auto ne risente","Per non compromettere il controllo del veicolo","Per poter conversare meglio","Perché la ricezione è migliore da fermi"],"correct":[1],"explanation":"Using the phone while moving can reduce your control of the vehicle.","explanation_it":"Usare il telefono in movimento può ridurre il controllo del veicolo.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS1.26","category":"Overtaking","question":"To overtake safely, which one of the following applies?","question_it":"Per sorpassare in sicurezza, quale delle seguenti azioni è corretta?","answers":["Check the speed and position of following traffic","Steer around the vehicle sharply","Get in close behind before moving out","Cut back in sharply after passing"],"answers_it":["Controllare velocità e posizione del traffico dietro","Sterzare bruscamente attorno al veicolo","Avvicinarsi molto prima di spostarsi","Rientrare bruscamente dopo il sorpasso"],"correct":[0],"explanation":"Before overtaking, check mirrors and the speed and position of traffic behind.","explanation_it":"Prima del sorpasso controlla gli specchi, la velocità e la posizione del traffico dietro.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS2.1","category":"Pedestrian crossings","question":"A pelican crossing that crosses the road in a straight line and has a central traffic island must be treated as:","question_it":"Un attraversamento pelican in linea retta con isola centrale deve essere considerato:","answers":["Two crossings during darkness","One complete crossing","Two separate crossings","One crossing in daylight only"],"answers_it":["Due attraversamenti di notte","Un unico attraversamento completo","Due attraversamenti separati","Un attraversamento solo di giorno"],"correct":[1],"explanation":"A straight pelican crossing with a central island is treated as one complete crossing.","explanation_it":"Un pelican crossing rettilineo con isola centrale è considerato un unico attraversamento.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS2.2","category":"Pedestrian crossings","question":"At a pelican crossing, what does the amber light mean? Select 2 answers.","question_it":"A un pelican crossing, cosa significa la luce gialla? Seleziona 2 risposte.","answers":["Give way to pedestrians already on the crossing","Stop and wait for the red light","Give way to pedestrians waiting to cross","Stop and wait for the green light"],"answers_it":["Dare precedenza ai pedoni già sull'attraversamento","Fermarsi e attendere la luce rossa","Dare precedenza ai pedoni in attesa","Fermarsi e attendere la luce verde"],"correct":[0,1],"explanation":"Amber means stop, and you must give way to pedestrians already crossing.","explanation_it":"La luce gialla impone di fermarsi e dare precedenza ai pedoni già in attraversamento.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS2.3","category":"Pedestrian crossings","question":"You are approaching a pelican crossing. The amber light is showing. You must: Select 2 answers.","question_it":"Ti avvicini a un pelican crossing con luce gialla. Devi: Seleziona 2 risposte.","answers":["Not move until the green light appears","Encourage pedestrians to cross","Keep on driving","Stop and wait for the red light even if the crossing is clear"],"answers_it":["Non muoverti finché non compare il verde","Incoraggiare i pedoni ad attraversare","Continuare a guidare","Fermarti e attendere il rosso anche se l'attraversamento è libero"],"correct":[0,3],"explanation":"Do not continue through an amber signal; stop and wait for the proper signal.","explanation_it":"Non proseguire con il giallo; fermati e attendi il segnale corretto.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS2.5","category":"Pedestrian crossings","question":"You have stopped at a zebra crossing to allow pedestrians to cross. You should:","question_it":"Ti sei fermato a un attraversamento zebra per far passare i pedoni. Devi:","answers":["Wait until they have crossed","Signal to pedestrians to cross","Wait while revving your engine","Edge your vehicle forward slowly"],"answers_it":["Attendere che abbiano attraversato","Fare cenno ai pedoni di attraversare","Attendere accelerando il motore","Avanzare lentamente"],"correct":[0],"explanation":"Remain stopped and patient until pedestrians have completed the crossing.","explanation_it":"Rimani fermo e paziente finché i pedoni non hanno completato l'attraversamento.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS2.7","category":"Pedestrian crossings","question":"At a zebra crossing you should:","question_it":"A un attraversamento zebra devi:","answers":["Wave pedestrians across","Park on the zigzag lines","Always leave it clear in traffic queues","Rev the engine to hurry pedestrians"],"answers_it":["Fare cenno ai pedoni di attraversare","Parcheggiare sulle linee a zig-zag","Lasciarlo sempre libero nelle code","Accelerare il motore per far sbrigare i pedoni"],"correct":[2],"explanation":"Never block a pedestrian crossing when traffic is queued.","explanation_it":"Non bloccare mai un attraversamento pedonale quando il traffico è in coda.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS2.8","category":"Pedestrian crossings","question":"You stopped for pedestrians waiting at a zebra crossing, but they did not start to cross. What should you do?","question_it":"Ti sei fermato per pedoni in attesa a un attraversamento zebra, ma non iniziano ad attraversare. Cosa devi fare?","answers":["Be patient and wait","Wave them across","Drive on","Sound your horn"],"answers_it":["Essere paziente e attendere","Fare cenno di attraversare","Proseguire","Suonare il clacson"],"correct":[0],"explanation":"Do not pressure pedestrians; remain patient and wait.","explanation_it":"Non mettere fretta ai pedoni; sii paziente e attendi.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS2.12","category":"Following distance","question":"When following another vehicle on the road you should not:","question_it":"Quando segui un altro veicolo sulla strada non devi:","answers":["Drive with rear fog lights off","Reverse into a parking space","Follow the vehicle too closely","Look through the rear-view mirror"],"answers_it":["Guidare con i retronebbia spenti","Entrare in retromarcia in un parcheggio","Seguire il veicolo troppo da vicino","Guardare nello specchietto retrovisore"],"correct":[2],"explanation":"Following too closely leaves insufficient space and time to stop.","explanation_it":"Seguire troppo da vicino non lascia spazio e tempo sufficienti per fermarsi.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS2.26","category":"Overtaking","question":"A heavy lorry is taking a long time to overtake you. What should you do?","question_it":"Un camion pesante impiega molto tempo a sorpassarti. Cosa devi fare?","answers":["Change direction","Slow down","Hold your speed","Speed up"],"answers_it":["Cambiare direzione","Rallentare","Mantenere la velocità","Accelerare"],"correct":[1],"explanation":"Slow down to help the lorry complete the overtaking manoeuvre safely.","explanation_it":"Rallenta per aiutare il camion a completare il sorpasso in sicurezza.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS2.33","category":"Signals","question":"You should only flash your headlights to other road users:","question_it":"Devi lampeggiare con i fari agli altri utenti soltanto:","answers":["To tell them you have right of way","To show you are about to reverse","To show that you are giving way","To let them know that you are there"],"answers_it":["Per dire che hai la precedenza","Per indicare che stai per fare retromarcia","Per mostrare che stai dando precedenza","Per segnalare la tua presenza"],"correct":[3],"explanation":"Headlight flashes should only warn others of your presence.","explanation_it":"Il lampeggio dei fari deve servire soltanto ad avvertire della tua presenza.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS2.36","category":"Positioning","question":"You are in a one-way street and want to turn right. Where should you position your vehicle?","question_it":"Sei in una strada a senso unico e vuoi girare a destra. Dove devi posizionarti?","answers":["Just left of the centre line","In either lane depending on traffic","In the left-hand lane","As close as safely possible to the right-hand side"],"answers_it":["Appena a sinistra della linea centrale","In una corsia qualsiasi secondo il traffico","Nella corsia sinistra","Il più vicino possibile in sicurezza al lato destro"],"correct":[3],"explanation":"On a one-way street, position near the right side before turning right.","explanation_it":"In una strada a senso unico posizionati vicino al lato destro prima di svoltare a destra.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS2.37","category":"Positioning","question":"Why should you take up the correct position in good time before turning right?","question_it":"Perché devi prendere per tempo la posizione corretta prima di girare a destra?","answers":["To allow drivers to pass on your right","To get a better view into the road","To help others know what you intend to do","To allow others to pull out in front"],"answers_it":["Per far passare i veicoli a destra","Per vedere meglio la strada","Per far capire agli altri cosa intendi fare","Per consentire agli altri di uscire davanti"],"correct":[2],"explanation":"Correct early positioning clearly communicates your intention.","explanation_it":"Posizionarsi correttamente per tempo comunica chiaramente la tua intenzione.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS2.41","category":"Signals","question":"When should you give signals? Select 2 answers.","question_it":"Quando devi dare un segnale? Seleziona 2 risposte.","answers":["After checking it is safe, before changing course, turning, stopping or moving off","Only when joining a dual carriageway","At all times to alert road users and pedestrians of intended actions","Only in darkness or bad weather","To gain priority over other traffic"],"answers_it":["Dopo aver controllato che sia sicuro, prima di cambiare direzione, svoltare, fermarti o partire","Solo entrando in una strada a più corsie","Ogni volta che serve ad avvertire utenti e pedoni delle tue intenzioni","Solo al buio o con maltempo","Per ottenere la precedenza"],"correct":[0,2],"explanation":"Signal after checking it is safe and whenever other road users may benefit.","explanation_it":"Segnala dopo aver controllato che sia sicuro e ogni volta che gli altri utenti possono trarne beneficio.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS3.1","category":"Vehicle safety","question":"Which fluid is dangerous if allowed to get low?","question_it":"Quale liquido è pericoloso se il livello diventa troppo basso?","answers":["Radiator coolant","Brake fluid","Battery water","Antifreeze"],"answers_it":["Liquido refrigerante","Liquido dei freni","Acqua della batteria","Antigelo"],"correct":[1],"explanation":"Low brake fluid may indicate a fault and can seriously affect braking.","explanation_it":"Un livello basso del liquido freni può indicare un guasto e compromettere seriamente la frenata.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS3.7","category":"Tyres","question":"When should tyre pressure be checked?","question_it":"Quando deve essere controllata la pressione degli pneumatici?","answers":["When tyres are hot","After driving at high speed","After a lengthy journey","When tyres are cold"],"answers_it":["Quando gli pneumatici sono caldi","Dopo aver guidato ad alta velocità","Dopo un lungo viaggio","Quando gli pneumatici sono freddi"],"correct":[3],"explanation":"Tyre pressures should be measured when the tyres are cold.","explanation_it":"La pressione deve essere misurata quando gli pneumatici sono freddi.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS3.9","category":"Tyres","question":"Driving with under-inflated tyres can affect: Select 2 answers.","question_it":"Guidare con pneumatici sgonfi può influire su: Seleziona 2 risposte.","answers":["Oil pressure","Braking","Fuel consumption","Engine temperature"],"answers_it":["Pressione dell'olio","Frenata","Consumo di carburante","Temperatura del motore"],"correct":[1,2],"explanation":"Under-inflation worsens braking and increases fuel consumption.","explanation_it":"La pressione insufficiente peggiora la frenata e aumenta il consumo di carburante.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS3.29","category":"Eco driving","question":"You will help the environment if you:","question_it":"Aiuterai l'ambiente se:","answers":["Accelerate and brake sharply","Drive continually using full choke","Reduce tyre pressure","Walk or cycle when you can"],"answers_it":["Acceleri e freni bruscamente","Guidi sempre con lo starter tirato","Riduci la pressione degli pneumatici","Cammini o usi la bicicletta quando possibile"],"correct":[3],"explanation":"Walking or cycling avoids unnecessary emissions.","explanation_it":"Camminare o andare in bicicletta evita emissioni inutili.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS3.30","category":"Eco driving","question":"To help the environment you should not:","question_it":"Per aiutare l'ambiente non devi:","answers":["Remove unnecessary weight from the boot","Use your vehicle for very short journeys","Walk, cycle or use public transport","Remove an unloaded roof rack"],"answers_it":["Rimuovere peso inutile dal bagagliaio","Usare il veicolo per tragitti molto brevi","Camminare, pedalare o usare il trasporto pubblico","Rimuovere il portapacchi vuoto"],"correct":[1],"explanation":"Very short journeys with a cold engine create unnecessary pollution and fuel use.","explanation_it":"I tragitti molto brevi a motore freddo causano consumo e inquinamento inutili.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS3.31","category":"Tyres","question":"Excessive or uneven tyre wear can be caused by faults in: Select 3 answers.","question_it":"L'usura eccessiva o irregolare degli pneumatici può essere causata da guasti a: Seleziona 3 risposte.","answers":["Exhaust system","Suspension","Accelerator","Gearbox","Wheel alignment","Braking system"],"answers_it":["Impianto di scarico","Sospensioni","Acceleratore","Cambio","Allineamento ruote","Impianto frenante"],"correct":[1,4,5],"explanation":"Suspension, alignment and braking faults can create uneven tyre wear.","explanation_it":"Guasti a sospensioni, allineamento e freni possono causare usura irregolare.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS3.33","category":"Eco driving","question":"Which actions reduce fuel consumption? Select 2 answers.","question_it":"Quali azioni riducono il consumo di carburante? Seleziona 2 risposte.","answers":["Planning well ahead","Reducing road speed","Rapid acceleration","Short cold-engine journeys","Driving in lower gears","Late harsh braking"],"answers_it":["Pianificare in anticipo","Ridurre la velocità","Accelerare rapidamente","Fare brevi tragitti a motore freddo","Guidare con marce basse","Frenare tardi e bruscamente"],"correct":[0,1],"explanation":"Planning and lower speed promote smooth, efficient driving.","explanation_it":"Pianificare e ridurre la velocità favoriscono una guida fluida ed efficiente.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS3.45","category":"Speed limits","question":"In some residential roads you will find a speed limit of:","question_it":"In alcune strade residenziali troverai un limite di velocità di:","answers":["80 kph","60 kph","35 kph","50 kph"],"answers_it":["80 km/h","60 km/h","35 km/h","50 km/h"],"correct":[2],"explanation":"Some residential roads use a 35 kph limit.","explanation_it":"Alcune strade residenziali hanno un limite di 35 km/h.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS3.46","category":"Traffic calming","question":"Road humps, chicanes and road narrowing are:","question_it":"Dossi, chicane e restringimenti stradali sono:","answers":["Found only at toll bridges","Used to increase traffic speed","Always found at major roadworks","Traffic-calming measures"],"answers_it":["Presenti solo ai ponti a pedaggio","Usati per aumentare la velocità","Sempre presenti nei grandi cantieri","Misure di moderazione del traffico"],"correct":[3],"explanation":"These features are designed to reduce traffic speed.","explanation_it":"Questi elementi sono progettati per ridurre la velocità del traffico.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS3.47","category":"Traffic calming","question":"You enter a road where there are road humps. You should:","question_it":"Entri in una strada con dossi. Devi:","answers":["Maintain a reduced speed throughout","Drive slowly only at school times","Always keep to the maximum legal speed","Accelerate between each hump"],"answers_it":["Mantenere una velocità ridotta per tutto il tratto","Rallentare solo negli orari scolastici","Mantenere sempre il limite massimo","Accelerare tra un dosso e l'altro"],"correct":[0],"explanation":"Keep a consistently reduced speed through the traffic-calmed area.","explanation_it":"Mantieni una velocità costantemente ridotta nell'area con moderazione del traffico.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS4.5","category":"Stopping distances","question":"On a good dry road with good brakes and tyres, what is the overall stopping distance at 48 kph?","question_it":"Su strada asciutta con freni e pneumatici efficienti, qual è la distanza totale di arresto a 48 km/h?","answers":["96 metres","53 metres","36 metres","23 metres"],"answers_it":["96 metri","53 metri","36 metri","23 metri"],"correct":[3],"explanation":"The stated overall stopping distance at 48 kph is 23 metres.","explanation_it":"La distanza totale indicata a 48 km/h è di 23 metri.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS4.6","category":"Vehicle control","question":"Braking hard at high speed on a sharp bend can make your vehicle:","question_it":"Frenare bruscamente ad alta velocità in una curva stretta può rendere il veicolo:","answers":["Corner safely","Unstable","Stall","More stable"],"answers_it":["Sicuro in curva","Instabile","Soggetto a spegnersi","Più stabile"],"correct":[1],"explanation":"Heavy braking in a bend can upset vehicle balance and cause loss of control.","explanation_it":"Una frenata intensa in curva può alterare l'equilibrio del veicolo e causare perdita di controllo.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS4.10","category":"Following distance","question":"The two-second rule allows you to:","question_it":"La regola dei due secondi ti permette di:","answers":["Keep a safe distance from the vehicle in front","Check your mirrors","Check your blind spot","Keep the correct distance from the kerb"],"answers_it":["Mantenere una distanza sicura dal veicolo davanti","Controllare gli specchi","Controllare l'angolo cieco","Mantenere la distanza dal marciapiede"],"correct":[0],"explanation":"It provides a simple method for measuring a safe following gap.","explanation_it":"È un metodo semplice per misurare una distanza di sicurezza.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS4.11","category":"Stopping distances","question":"Your overall stopping distance will be longer when driving:","question_it":"La distanza totale di arresto sarà maggiore guidando:","answers":["In the rain","In strong winds","At night","In fog"],"answers_it":["Sotto la pioggia","Con vento forte","Di notte","Nella nebbia"],"correct":[0],"explanation":"Wet roads reduce tyre grip and increase stopping distance.","explanation_it":"La strada bagnata riduce l'aderenza e aumenta la distanza di arresto.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS4.16","category":"Skidding","question":"What is the main cause of skidding?","question_it":"Qual è la causa principale dello slittamento?","answers":["The road","The driver","The vehicle","The weather"],"answers_it":["La strada","Il conducente","Il veicolo","Il tempo"],"correct":[1],"explanation":"Skids are usually caused by driver actions such as excessive speed, steering or braking.","explanation_it":"Gli slittamenti sono normalmente causati da azioni del conducente, come velocità, sterzata o frenata eccessive.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS4.21","category":"Hot weather","question":"In very hot weather the road surface can become soft. Which two things are affected most?","question_it":"Con molto caldo il manto stradale può ammorbidirsi. Quali due elementi sono più influenzati?","answers":["Windscreen","Steering","Suspension","Braking"],"answers_it":["Parabrezza","Sterzo","Sospensioni","Frenata"],"correct":[1,3],"explanation":"A soft road surface can reduce steering precision and braking grip.","explanation_it":"Un manto morbido può ridurre la precisione dello sterzo e l'aderenza in frenata.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS4.22","category":"Signals","question":"Your indicators may be difficult to see in bright sunlight. What should you do?","question_it":"Gli indicatori possono essere difficili da vedere con sole forte. Cosa devi fare?","answers":["Turn as quickly as possible","Give an arm signal as well as using the indicator","Touch the brakes several times","Use the indicator earlier"],"answers_it":["Svoltare il più rapidamente possibile","Fare anche un segnale con il braccio","Premere più volte il freno","Usare prima l'indicatore"],"correct":[1],"explanation":"An arm signal can reinforce an indicator that may be hard to see.","explanation_it":"Un segnale con il braccio può rendere più chiara un'indicazione poco visibile.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS4.25","category":"Vehicle control","question":"How can you use the engine of your vehicle as a brake?","question_it":"Come puoi usare il motore del veicolo come freno?","answers":["Select neutral","Change to a higher gear","Select reverse","Change to a lower gear"],"answers_it":["Mettere in folle","Inserire una marcia più alta","Inserire la retromarcia","Inserire una marcia più bassa"],"correct":[3],"explanation":"A lower gear provides engine braking.","explanation_it":"Una marcia più bassa produce freno motore.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS4.27","category":"Traffic calming","question":"You are approaching road humps in a residential area. You should:","question_it":"Ti avvicini a dossi in una zona residenziale. Devi:","answers":["Stop and check both pavements","Wait for pedestrians to cross","Slow your vehicle right down","Move to the left side"],"answers_it":["Fermarti e controllare entrambi i marciapiedi","Attendere che attraversino i pedoni","Ridurre molto la velocità","Spostarti sul lato sinistro"],"correct":[2],"explanation":"Reduce speed significantly before road humps.","explanation_it":"Riduci sensibilmente la velocità prima dei dossi.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS4.28","category":"Bends","question":"When approaching a right-hand bend, why should you keep well to the left?","question_it":"Avvicinandoti a una curva a destra, perché devi tenerti bene a sinistra?","answers":["To be safer if the vehicle skids","To let traffic behind overtake","To overcome the road slope","To improve your view of the road"],"answers_it":["Per essere più sicuro in caso di slittamento","Per far sorpassare chi segue","Per compensare la pendenza","Per migliorare la visuale della strada"],"correct":[3],"explanation":"A left position gives a better view around a right-hand bend.","explanation_it":"La posizione a sinistra offre una visuale migliore attorno a una curva a destra.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS4.29","category":"Bends","question":"You are approaching a right-hand bend. You should:","question_it":"Ti avvicini a una curva a destra. Devi:","answers":["Keep right to make the bend less sharp","Keep left for a better view","Keep right to avoid the gutter","Keep left because it makes the bend faster"],"answers_it":["Tenerti a destra per rendere la curva meno stretta","Tenerti a sinistra per vedere meglio","Tenerti a destra per evitare il bordo","Tenerti a sinistra per affrontarla più velocemente"],"correct":[1],"explanation":"Keeping left improves your view and safety through the bend.","explanation_it":"Tenersi a sinistra migliora la visuale e la sicurezza in curva.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS5.3","category":"Eyesight","question":"A driver can read a number plate at the required distance only with glasses. When should the glasses be worn?","question_it":"Un conducente riesce a leggere la targa alla distanza richiesta solo con gli occhiali. Quando deve indossarli?","answers":["All the time when driving","Only in poor visibility","Only when reversing","Only on long journeys"],"answers_it":["Sempre durante la guida","Solo con scarsa visibilità","Solo in retromarcia","Solo nei lunghi viaggi"],"correct":[0],"explanation":"Required corrective lenses must be worn whenever driving.","explanation_it":"Le lenti correttive necessarie devono essere indossate ogni volta che si guida.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS5.4","category":"Eyesight","question":"You cannot find the glasses you need for driving. What should you do?","question_it":"Non trovi gli occhiali necessari per guidare. Cosa devi fare?","answers":["Drive home at night","Borrow a friend's glasses","Drive slowly on quiet roads","Find another way home without driving"],"answers_it":["Guidare a casa di notte","Prendere gli occhiali di un amico","Guidare lentamente su strade tranquille","Trovare un altro modo per tornare senza guidare"],"correct":[3],"explanation":"Do not drive without the corrective lenses you need.","explanation_it":"Non guidare senza le lenti correttive di cui hai bisogno.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS5.5","category":"Eyesight","question":"You must wear glasses or contact lenses while driving if:","question_it":"Devi indossare occhiali o lenti a contatto durante la guida se:","answers":["There is an eyesight problem in your family","You cannot read a number plate from 36 metres","You hold an orange badge","You cannot read a number plate from 20.5 metres without them"],"answers_it":["Ci sono problemi di vista in famiglia","Non leggi una targa da 36 metri","Possiedi un contrassegno arancione","Non leggi una targa da 20,5 metri senza lenti"],"correct":[3],"explanation":"Corrective lenses are required if you cannot meet the eyesight standard without them.","explanation_it":"Le lenti sono obbligatorie se senza di esse non soddisfi il requisito visivo.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS5.7","category":"Alcohol","question":"Which three are likely effects of drinking alcohol on driving?","question_it":"Quali tre sono probabili effetti dell'alcol sulla guida?","answers":["Poor judgement","Increased confidence","Colour blindness","Faster reactions","Increased concentration","Reduced coordination"],"answers_it":["Scarso giudizio","Maggiore sicurezza in sé","Daltonismo","Reazioni più rapide","Maggiore concentrazione","Coordinazione ridotta"],"correct":[0,1,5],"explanation":"Alcohol impairs judgement and coordination while creating false confidence.","explanation_it":"L'alcol compromette giudizio e coordinazione e crea falsa sicurezza.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS5.8","category":"Alcohol","question":"Drinking any amount of alcohol is likely to: Select 3 answers.","question_it":"Bere qualsiasi quantità di alcol può: Seleziona 3 risposte.","answers":["Give a false sense of confidence","Improve awareness of danger","Increase reaction speed","Worsen judgement of speed","Slow reactions to hazards"],"answers_it":["Dare un falso senso di sicurezza","Migliorare la percezione del pericolo","Aumentare la velocità di reazione","Peggiorare la valutazione della velocità","Rallentare le reazioni ai pericoli"],"correct":[0,3,4],"explanation":"Alcohol creates false confidence, worsens judgement and slows reactions.","explanation_it":"L'alcol crea falsa sicurezza, peggiora il giudizio e rallenta le reazioni.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS5.9","category":"Alcohol","question":"You are invited to a pub lunch and must drive in the evening. What is the best course of action?","question_it":"Sei invitato a pranzo in un pub e devi guidare la sera. Qual è la scelta migliore?","answers":["Eat a hot meal with alcohol","Drink milk before alcohol","Avoid mixing drinks","Do not drink any alcohol"],"answers_it":["Mangiare caldo insieme all'alcol","Bere latte prima dell'alcol","Non mescolare bevande","Non bere alcun alcolico"],"correct":[3],"explanation":"The safest choice when you must drive is not to drink any alcohol.","explanation_it":"La scelta più sicura quando devi guidare è non bere alcol.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS5.11","category":"Alcohol","question":"How does alcohol affect your driving?","question_it":"Come influisce l'alcol sulla guida?","answers":["Improves coordination","Increases awareness","Speeds up reactions","Reduces concentration"],"answers_it":["Migliora la coordinazione","Aumenta l'attenzione","Accelera le reazioni","Riduce la concentrazione"],"correct":[3],"explanation":"Alcohol reduces concentration and safe driving ability.","explanation_it":"L'alcol riduce la concentrazione e la capacità di guidare in sicurezza.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS6.55","category":"Vulnerable road users","question":"A horse rider is in the left-hand lane approaching a roundabout. The driver behind should expect the rider to:","question_it":"Un cavaliere è nella corsia sinistra avvicinandosi a una rotatoria. Il conducente dietro deve aspettarsi che il cavaliere possa:","answers":["Go ahead","Turn left","Turn right","Go in any direction"],"answers_it":["Proseguire dritto","Girare a sinistra","Girare a destra","Andare in qualsiasi direzione"],"correct":[3],"explanation":"Horse riders may position differently for safety, so do not assume their direction.","explanation_it":"I cavalieri possono posizionarsi in modo diverso per sicurezza, quindi non presumere la loro direzione.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS6.56","category":"Vulnerable road users","question":"You are approaching a roundabout. There are horses just ahead of you. What should you do? Select 2 answers.","question_it":"Ti avvicini a una rotatoria e ci sono cavalli davanti. Cosa devi fare? Seleziona 2 risposte.","answers":["Sound your horn as a warning","Give them plenty of room","Accelerate past as quickly as possible","Treat them like any other vehicle","Be prepared to stop"],"answers_it":["Suonare il clacson come avvertimento","Lasciare molto spazio","Accelerare per superarli rapidamente","Trattarli come qualsiasi altro veicolo","Essere pronto a fermarti"],"correct":[1,4],"explanation":"Give horses plenty of room and be prepared to stop because they may react unpredictably.","explanation_it":"Lascia molto spazio ai cavalli e preparati a fermarti perché possono reagire in modo imprevedibile.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS6.57","category":"Vulnerable road users","question":"You see a group of horse riders approaching a roundabout. They are signalling right but keeping well to the left. What should you do?","question_it":"Vedi un gruppo di cavalieri avvicinarsi a una rotatoria. Segnalano a destra ma restano molto a sinistra. Cosa devi fare?","answers":["Cut in front of them","Keep close to them","Proceed as normal","Stay well back"],"answers_it":["Tagliare loro la strada","Restare vicino a loro","Procedere normalmente","Restare ben distante"],"correct":[3],"explanation":"Horse riders may need extra space to turn safely, so stay well back.","explanation_it":"I cavalieri possono aver bisogno di più spazio per svoltare in sicurezza, quindi resta ben distante.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS6.58","category":"Accident prevention","question":"What is the most common cause of road accidents?","question_it":"Qual è la causa più comune degli incidenti stradali?","answers":["Mechanical failure","Driver error","Road conditions","Weather conditions"],"answers_it":["Guasto meccanico","Errore del conducente","Condizioni della strada","Condizioni meteorologiche"],"correct":[1],"explanation":"Driver error is the most common cause of road accidents.","explanation_it":"L'errore del conducente è la causa più comune degli incidenti stradali.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS6.60","category":"Hazard awareness","question":"Which age group is most likely to be involved in traffic accidents?","question_it":"Quale fascia d'età è più coinvolta negli incidenti stradali?","answers":["46 to 55 years old","55 years old and over","36 to 45 years old","18 to 25 years old"],"answers_it":["Da 46 a 55 anni","55 anni e oltre","Da 36 a 45 anni","Da 18 a 25 anni"],"correct":[3],"explanation":"Young drivers aged 18 to 25 are statistically more likely to be involved in traffic accidents.","explanation_it":"I giovani conducenti tra 18 e 25 anni sono statisticamente più coinvolti negli incidenti.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS6.61","category":"Attitude","question":"You are following a learner driver who stalls at a junction. What should you do?","question_it":"Segui un principiante che spegne il motore a un incrocio. Cosa devi fare?","answers":["Be patient because learners may make mistakes","Immediately steer around and drive on","Rev your engine if they take too long","Drive close behind and flash your headlights"],"answers_it":["Essere paziente perché i principianti possono sbagliare","Superarlo immediatamente","Accelerare il motore se impiega troppo","Avvicinarti e lampeggiare"],"correct":[0],"explanation":"Be patient and avoid pressuring an inexperienced driver.","explanation_it":"Sii paziente e non mettere sotto pressione un conducente inesperto.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS7.4","category":"Large vehicles","question":"You are waiting to emerge left from a minor road. A large vehicle is approaching from the right. You have time to turn, but should wait. Why?","question_it":"Aspetti di immetterti a sinistra da una strada secondaria. Un veicolo grande arriva da destra. Avresti tempo, ma devi aspettare. Perché?","answers":["It can hide vehicles from the left","It is difficult to steer straight","It may turn suddenly","It can hide an overtaking vehicle"],"answers_it":["Può nascondere veicoli provenienti da sinistra","È difficile da mantenere diritto","Può svoltare improvvisamente","Può nascondere un veicolo in sorpasso"],"correct":[3],"explanation":"A large vehicle may hide a vehicle overtaking it.","explanation_it":"Un veicolo grande può nascondere un veicolo che lo sta sorpassando.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS9.7","category":"Dual carriageways","question":"What should you use the hard shoulder of a multi-lane carriageway for?","question_it":"Per cosa devi usare la corsia di emergenza di una strada a più corsie?","answers":["Stopping in an emergency","Joining the carriageway","Stopping when tired","Leaving the carriageway"],"answers_it":["Fermarti in emergenza","Immetterti nella carreggiata","Fermarti quando sei stanco","Uscire dalla carreggiata"],"correct":[0],"explanation":"The hard shoulder is for emergencies only.","explanation_it":"La corsia di emergenza va usata solo in caso di emergenza.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS9.8","category":"Dual carriageways","question":"After a breakdown, how should you rejoin a multi-lane carriageway from the hard shoulder?","question_it":"Dopo un guasto, come devi rientrare nella carreggiata dalla corsia di emergenza?","answers":["Wait until someone flashes you","Move out using hazard lights","Gain speed on the hard shoulder before moving out","Move out first then accelerate"],"answers_it":["Aspettare che qualcuno lampeggi","Rientrare con le quattro frecce","Aumentare la velocità sulla corsia di emergenza prima di rientrare","Rientrare e poi accelerare"],"correct":[2],"explanation":"Build up speed on the hard shoulder before merging when it is safe.","explanation_it":"Aumenta la velocità sulla corsia di emergenza prima di immetterti quando è sicuro.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS9.9","category":"Following distance","question":"The minimum safe time gap in good conditions is at least:","question_it":"L'intervallo minimo di sicurezza in buone condizioni è almeno:","answers":["Three seconds","One second","Four seconds","Two seconds"],"answers_it":["Tre secondi","Un secondo","Quattro secondi","Due secondi"],"correct":[3],"explanation":"In good conditions, keep at least a two-second gap.","explanation_it":"In buone condizioni mantieni almeno due secondi di distanza.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS9.10","category":"Dual carriageways","question":"You intend to leave a multi-lane carriageway at the next exit. Where should you normally position your vehicle?","question_it":"Vuoi uscire da una strada a più corsie alla prossima uscita. Dove devi normalmente posizionarti?","answers":["In any lane","In the left-hand lane","On the hard shoulder","In the middle lane"],"answers_it":["In qualsiasi corsia","Nella corsia sinistra","Sulla corsia di emergenza","Nella corsia centrale"],"correct":[1],"explanation":"Move into the left-hand lane in good time before your exit.","explanation_it":"Spostati per tempo nella corsia sinistra prima dell'uscita.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS9.11","category":"Dual carriageways","question":"You pass the exit you wanted on a multi-lane carriageway. What should you do?","question_it":"Superi per errore l'uscita desiderata su una strada a più corsie. Cosa devi fare?","answers":["Make a U-turn at the next gap","Carry on to the next exit","Reverse in the left lane","Reverse on the hard shoulder"],"answers_it":["Fare inversione al prossimo varco","Proseguire fino alla prossima uscita","Fare retromarcia nella corsia sinistra","Fare retromarcia sulla corsia di emergenza"],"correct":[1],"explanation":"Never reverse or turn around; continue to the next exit.","explanation_it":"Non fare mai retromarcia o inversione; prosegui fino alla prossima uscita.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS10.1","category":"Rules of the road","question":"When may you drive over a footpath?","question_it":"Quando puoi guidare sopra un marciapiede?","answers":["If no pedestrians are near","When it is very wide","To overtake slow traffic","To gain lawful access to a property"],"answers_it":["Se non ci sono pedoni","Quando è molto largo","Per sorpassare traffico lento","Per accedere legalmente a una proprietà"],"correct":[3],"explanation":"You may cross a footpath only for lawful access to property.","explanation_it":"Puoi attraversare il marciapiede solo per accedere legalmente a una proprietà.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS10.3","category":"Speed limits","question":"What is the national speed limit outside built-up areas for cars and motorcycles unless otherwise indicated?","question_it":"Qual è il limite nazionale fuori dai centri abitati per auto e moto, salvo diversa indicazione?","answers":["100 kph","60 kph","80 kph","50 kph"],"answers_it":["100 km/h","60 km/h","80 km/h","50 km/h"],"correct":[2],"explanation":"The national limit outside built-up areas is 80 kph unless signs state otherwise.","explanation_it":"Il limite nazionale fuori dai centri abitati è 80 km/h salvo diversa segnalazione.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS10.6","category":"Speed limits","question":"What does a maximum speed limit sign mean?","question_it":"Cosa significa un segnale di limite massimo di velocità?","answers":["The speed is safe in all conditions","The speed is only advised","The speed may be exceeded when clear","You must not exceed the speed shown"],"answers_it":["La velocità è sicura in ogni condizione","La velocità è solo consigliata","Può essere superata se la strada è libera","Non devi superare la velocità indicata"],"correct":[3],"explanation":"The number shown is the legal maximum, not a target.","explanation_it":"Il numero indicato è il massimo legale, non una velocità da raggiungere.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS12.8","category":"Documents","question":"Which two pieces of information are found on a vehicle registration document?","question_it":"Quali due informazioni si trovano sul documento di registrazione del veicolo?","answers":["Make of the vehicle","Registered owner","Type of insurance cover","Date of VRT","Service history"],"answers_it":["Marca del veicolo","Proprietario registrato","Tipo di assicurazione","Data del VRT","Storico manutenzione"],"correct":[0,1],"explanation":"The registration document records the vehicle make and registered owner.","explanation_it":"Il documento di registrazione riporta la marca e il proprietario registrato.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS12.11","category":"Documents","question":"Who is responsible for ensuring that a vehicle is fully roadworthy when driven on a public road?","question_it":"Chi è responsabile di assicurarsi che il veicolo sia pienamente idoneo alla circolazione?","answers":["Nobody in particular","Your mechanic","The VRT tester","You, the driver"],"answers_it":["Nessuno in particolare","Il meccanico","L'esaminatore VRT","Tu, il conducente"],"correct":[3],"explanation":"The driver is responsible for the vehicle's roadworthiness when using it.","explanation_it":"Il conducente è responsabile dell'idoneità del veicolo quando lo usa.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS13.1","category":"Accidents","question":"At the scene of an accident you should:","question_it":"Sul luogo di un incidente devi:","answers":["Not put yourself at risk","Leave engines running","Pull everybody from vehicles","Go first to those screaming"],"answers_it":["Non mettere te stesso in pericolo","Lasciare i motori accesi","Estrarre tutti dai veicoli","Andare prima da chi urla"],"correct":[0],"explanation":"Your first priority is to avoid becoming another casualty.","explanation_it":"La prima priorità è evitare di diventare un'altra vittima.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS13.2","category":"Accidents","question":"You are first to arrive at an accident. Which four actions should you take?","question_it":"Sei il primo ad arrivare a un incidente. Quali quattro azioni devi compiere?","answers":["Warn other traffic","Call emergency services","Move uninjured people away","Switch off vehicle engines","Leave when another motorist arrives","Give casualties a drink"],"answers_it":["Avvertire il traffico","Chiamare i soccorsi","Allontanare le persone non ferite","Spegnere i motori","Andartene quando arriva un altro automobilista","Dare da bere ai feriti"],"correct":[0,1,2,3],"explanation":"Secure the scene, call for help, move uninjured people away and switch off engines.","explanation_it":"Metti in sicurezza la zona, chiama aiuto, allontana i non feriti e spegni i motori.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"CARS13.3","category":"Accidents","question":"You are first at an accident where people are badly injured. Which three actions should you take?","question_it":"Sei il primo a un incidente con feriti gravi. Quali tre azioni devi compiere?","answers":["Move injured people from vehicles","Give injured people a drink","Move uninjured people away","Ensure someone calls an ambulance","Switch on your hazard lights"],"answers_it":["Estrarre i feriti dai veicoli","Dare da bere ai feriti","Allontanare i non feriti","Assicurarti che qualcuno chiami un'ambulanza","Accendere le quattro frecce"],"correct":[2,3,4],"explanation":"Protect the scene, call an ambulance and move only uninjured people away.","explanation_it":"Proteggi la zona, chiama un'ambulanza e allontana solo le persone non ferite.","source":"Transport Malta Cars Version 4","status":"verified"},{"id":"LPTV2026.001","category":"LPTV Law 2026","question":"From 29 July 2026, for how long must an applicant have held a valid EU Category B driving licence before applying for an LPTV Driver Permit Tag?","question_it":"Dal 29 luglio 2026, da quanto tempo un candidato deve possedere una patente B UE valida prima di richiedere il tag LPTV?","answers":["At least 6 months","At least 1 year","At least 2 years","At least 5 years"],"answers_it":["Almeno 6 mesi","Almeno 1 anno","Almeno 2 anni","Almeno 5 anni"],"correct":[2],"explanation":"The new eligibility requirement is at least two years of holding a valid EU Category B driving licence.","explanation_it":"Il nuovo requisito prevede il possesso di una patente B UE valida da almeno due anni.","source":"Transport Malta - Changes Effective from 29 July 2026","status":"verified"},{"id":"LPTV2026.002","category":"LPTV Law 2026","question":"At the time of applying for an LPTV Driver Permit Tag, what is the maximum number of penalty points allowed?","question_it":"Al momento della richiesta del tag LPTV, qual è il numero massimo di punti di penalità consentito?","answers":["3 points","6 points","9 points","12 points"],"answers_it":["3 punti","6 punti","9 punti","12 punti"],"correct":[1],"explanation":"Applicants must have no more than six penalty points.","explanation_it":"Il candidato non deve avere più di sei punti di penalità.","source":"Transport Malta - Changes Effective from 29 July 2026","status":"verified"},{"id":"LPTV2026.003","category":"LPTV Law 2026","question":"How many passengers, besides the driver, may a light passenger transport vehicle carry?","question_it":"Quanti passeggeri, oltre al conducente, può trasportare un veicolo LPTV?","answers":["Up to 6","Up to 7","Up to 8","Up to 9"],"answers_it":["Fino a 6","Fino a 7","Fino a 8","Fino a 9"],"correct":[2],"explanation":"An LPTV may carry up to eight passengers besides the driver.","explanation_it":"Un LPTV può trasportare fino a otto passeggeri oltre al conducente.","source":"Transport Malta - Light Passenger Vehicle","status":"verified"},{"id":"LPTV2026.004","category":"Parking","question":"When a Y-plate vehicle is parked on the road and not in use, what must be clearly displayed?","question_it":"Quando un veicolo con targa Y è parcheggiato su strada e non è in uso, cosa deve essere esposto chiaramente?","answers":["A handwritten note","The official Transport Malta parking clock","A copy of the insurance certificate","The driver's ID card"],"answers_it":["Un biglietto scritto a mano","L'orologio ufficiale Transport Malta","Una copia dell'assicurazione","La carta d'identità del conducente"],"correct":[1],"explanation":"The official Transport Malta parking clock must be displayed and correctly set.","explanation_it":"Deve essere esposto e impostato correttamente l'orologio ufficiale Transport Malta.","source":"Transport Malta - Changes Effective from 29 July 2026","status":"verified"},{"id":"LPTV2026.005","category":"Parking","question":"For how long may a Y-plate vehicle remain parked on the road between 05:01 and 16:59?","question_it":"Per quanto tempo può restare parcheggiato su strada un veicolo con targa Y tra le 05:01 e le 16:59?","answers":["30 minutes","1 hour","2 hours","3 hours"],"answers_it":["30 minuti","1 ora","2 ore","3 ore"],"correct":[2],"explanation":"The daytime on-street parking limit is two hours.","explanation_it":"Il limite di sosta su strada durante il giorno è di due ore.","source":"Transport Malta - Changes Effective from 29 July 2026","status":"verified"},{"id":"LPTV2026.006","category":"Parking","question":"For how long may a Y-plate vehicle remain parked on the road between 17:00 and 05:00?","question_it":"Per quanto tempo può restare parcheggiato su strada un veicolo con targa Y tra le 17:00 e le 05:00?","answers":["30 minutes","1 hour","2 hours","3 hours"],"answers_it":["30 minuti","1 ora","2 ore","3 ore"],"correct":[1],"explanation":"The night-time on-street parking limit is one hour.","explanation_it":"Il limite di sosta su strada durante la notte è di un'ora.","source":"Transport Malta - Changes Effective from 29 July 2026","status":"verified"},{"id":"LPTV2026.007","category":"Parking","question":"What administrative penalty may apply for failing to display or correctly use the official Transport Malta parking clock?","question_it":"Quale sanzione amministrativa può essere applicata se non si espone o non si usa correttamente l'orologio ufficiale Transport Malta?","answers":["€50","€100","€250","€500"],"answers_it":["€50","€100","€250","€500"],"correct":[3],"explanation":"Failure to display or correctly use the official parking clock may result in a €500 penalty.","explanation_it":"La mancata esposizione o l'uso scorretto dell'orologio può comportare una sanzione di €500.","source":"Transport Malta - Changes Effective from 29 July 2026","status":"verified"},{"id":"LPTV2026.008","category":"Garaging","question":"Does the on-street parking allowance replace the operator's obligation to have approved garaging facilities?","question_it":"La possibilità di parcheggiare su strada sostituisce l'obbligo dell'operatore di avere un garage approvato?","answers":["Yes, always","Yes, but only at night","No","Only for operators with one vehicle"],"answers_it":["Sì, sempre","Sì, ma solo di notte","No","Solo per operatori con un veicolo"],"correct":[2],"explanation":"On-street parking is only an exception and does not replace approved garaging obligations.","explanation_it":"La sosta su strada è solo un'eccezione e non sostituisce l'obbligo di garaging approvato.","source":"Transport Malta - Changes Effective from 29 July 2026","status":"verified"},{"id":"LPTV2026.009","category":"Driving and rest periods","question":"What is the maximum time an LPTV driver may work in any 24-hour period?","question_it":"Qual è il tempo massimo di lavoro consentito a un conducente LPTV in qualsiasi periodo di 24 ore?","answers":["8 hours","10 hours","12 hours","14 hours"],"answers_it":["8 ore","10 ore","12 ore","14 ore"],"correct":[2],"explanation":"A driver must not work for more than twelve hours in any twenty-four-hour period.","explanation_it":"Un conducente non deve lavorare più di dodici ore in qualsiasi periodo di ventiquattro ore.","source":"Transport Malta - Changes Effective from 29 July 2026","status":"verified"},{"id":"LPTV2026.010","category":"Driving and rest periods","question":"What weekly rest must an LPTV driver have?","question_it":"Quale riposo settimanale deve avere un conducente LPTV?","answers":["At least half a day","At least one day","At least two days","No fixed weekly rest"],"answers_it":["Almeno mezza giornata","Almeno un giorno","Almeno due giorni","Nessun riposo settimanale fisso"],"correct":[1],"explanation":"Drivers must have at least one day of rest every week.","explanation_it":"I conducenti devono avere almeno un giorno di riposo ogni settimana.","source":"Transport Malta - Changes Effective from 29 July 2026","status":"verified"},{"id":"LPTV2026.011","category":"Intermediary booking platforms","question":"What technology must intermediary booking platforms use to verify a driver's identity?","question_it":"Quale tecnologia devono usare le piattaforme di prenotazione per verificare l'identità del conducente?","answers":["Fingerprint scanning only","Facial-recognition technology","A handwritten signature","Vehicle GPS only"],"answers_it":["Solo impronte digitali","Tecnologia di riconoscimento facciale","Firma scritta a mano","Solo GPS del veicolo"],"correct":[1],"explanation":"Platforms must use facial recognition to verify that the authorised driver is using the account.","explanation_it":"Le piattaforme devono usare il riconoscimento facciale per verificare che l'account sia usato dal conducente autorizzato.","source":"Transport Malta - Changes Effective from 29 July 2026","status":"verified"},{"id":"LPTV2026.012","category":"Intermediary booking platforms","question":"May an LPTV driver allow another person to use his or her driver account to provide passenger transport services?","question_it":"Un conducente LPTV può permettere a un'altra persona di usare il proprio account per svolgere servizi di trasporto?","answers":["Yes, if the other person has experience","Yes, for up to one hour","No","Only with the passenger's permission"],"answers_it":["Sì, se l'altra persona ha esperienza","Sì, per massimo un'ora","No","Solo con il permesso del passeggero"],"correct":[2],"explanation":"A driver must not allow another person to use his or her account or profile.","explanation_it":"Il conducente non deve permettere ad altri di usare il proprio account o profilo.","source":"Transport Malta - Changes Effective from 29 July 2026","status":"verified"},{"id":"LPTV2026.013","category":"Operator responsibilities","question":"May the number of authorised vehicles under an Operator Licence exceed the number of registered drivers?","question_it":"Il numero di veicoli autorizzati sotto una licenza operatore può superare il numero di conducenti registrati?","answers":["Yes","No","Only for LPTV2 operators","Only during weekends"],"answers_it":["Sì","No","Solo per operatori LPTV2","Solo nei fine settimana"],"correct":[1],"explanation":"The number of authorised vehicles cannot exceed the number of legally employed or commissioned and registered drivers.","explanation_it":"Il numero di veicoli autorizzati non può superare il numero di conducenti legalmente impiegati o incaricati e registrati.","source":"Transport Malta - Changes Effective from 29 July 2026","status":"verified"},{"id":"LPTV2026.014","category":"Administrative penalties","question":"What is the fine for the first to fourth garaging or parking infringement within the previous 12 months?","question_it":"Qual è la multa dalla prima alla quarta violazione di garaging o parcheggio nei 12 mesi precedenti?","answers":["€50","€100","€200","€500"],"answers_it":["€50","€100","€200","€500"],"correct":[1],"explanation":"For breaches 1 to 4, the staggered fine is €100.","explanation_it":"Dalla prima alla quarta violazione, la multa progressiva è di €100.","source":"Transport Malta - Changes Effective from 29 July 2026","status":"verified"},{"id":"LPTV2026.015","category":"Administrative penalties","question":"What is the fine for the fifth or sixth garaging or parking infringement within the previous 12 months?","question_it":"Qual è la multa per la quinta o sesta violazione di garaging o parcheggio nei 12 mesi precedenti?","answers":["€100","€200","€300","€400"],"answers_it":["€100","€200","€300","€400"],"correct":[1],"explanation":"For breaches 5 and 6, the staggered fine is €200.","explanation_it":"Per la quinta e la sesta violazione, la multa progressiva è di €200.","source":"Transport Malta - Changes Effective from 29 July 2026","status":"verified"},{"id":"LPTV2026.016","category":"Administrative penalties","question":"What is the fine for the seventh or eighth garaging or parking infringement within the previous 12 months?","question_it":"Qual è la multa per la settima o ottava violazione di garaging o parcheggio nei 12 mesi precedenti?","answers":["€100","€200","€300","€500"],"answers_it":["€100","€200","€300","€500"],"correct":[2],"explanation":"For breaches 7 and 8, the staggered fine is €300.","explanation_it":"Per la settima e l'ottava violazione, la multa progressiva è di €300.","source":"Transport Malta - Changes Effective from 29 July 2026","status":"verified"},{"id":"LPTV2026.017","category":"Administrative penalties","question":"What is the fine for the ninth or tenth garaging or parking infringement within the previous 12 months?","question_it":"Qual è la multa per la nona o decima violazione di garaging o parcheggio nei 12 mesi precedenti?","answers":["€200","€300","€400","€500"],"answers_it":["€200","€300","€400","€500"],"correct":[2],"explanation":"For breaches 9 and 10, the staggered fine is €400.","explanation_it":"Per la nona e la decima violazione, la multa progressiva è di €400.","source":"Transport Malta - Changes Effective from 29 July 2026","status":"verified"},{"id":"LPTV2026.018","category":"Administrative penalties","question":"What is the fine for eleven or more garaging or parking infringements within the previous 12 months?","question_it":"Qual è la multa per undici o più violazioni di garaging o parcheggio nei 12 mesi precedenti?","answers":["€300","€400","€500","€750"],"answers_it":["€300","€400","€500","€750"],"correct":[2],"explanation":"For eleven or more breaches, the staggered fine is €500.","explanation_it":"Per undici o più violazioni, la multa progressiva è di €500.","source":"Transport Malta - Changes Effective from 29 July 2026","status":"verified"},{"id":"LPTV2026.019","category":"Operator licences","question":"Which operator licence category is for Special Occasion Vehicles?","question_it":"Quale categoria di licenza operatore riguarda i veicoli per occasioni speciali?","answers":["LPTV1","LPTV2","SOV","PTV"],"answers_it":["LPTV1","LPTV2","SOV","PTV"],"correct":[2],"explanation":"Special Occasion Vehicles operate under an SOV Operator Licence.","explanation_it":"I veicoli per occasioni speciali operano con una licenza SOV.","source":"Transport Malta - Changes Effective from 29 July 2026","status":"verified"},{"id":"LPTV2026.020","category":"Special Occasion Vehicles","question":"May an SOV vehicle operate through an intermediary booking platform?","question_it":"Un veicolo SOV può operare tramite una piattaforma intermediaria di prenotazione?","answers":["Yes, without restriction","Yes, only at weekends","No","Only for airport transfers"],"answers_it":["Sì, senza restrizioni","Sì, solo nei fine settimana","No","Solo per trasferimenti aeroportuali"],"correct":[2],"explanation":"SOV vehicles cannot operate through intermediary booking platforms.","explanation_it":"I veicoli SOV non possono operare tramite piattaforme intermediarie di prenotazione.","source":"Transport Malta - Changes Effective from 29 July 2026","status":"verified"},{"id":"SCHOOL.001","category":"First aid and shock","status":"school_material_confirmed","question":"When treating someone for shock, what should you do? Select 2 answers.","question_it":"Quando soccorri una persona in stato di shock, cosa devi fare? Seleziona 2 risposte.","answers":["Reassure them","Loosen tight clothing","Give them alcohol","Make them walk around"],"answers_it":["Rassicurarla","Allentare gli indumenti stretti","Darle alcol","Farla camminare"],"correct":[0,1],"explanation":"A casualty in shock should be reassured and tight clothing should be loosened. Do not give alcohol or make them walk.","explanation_it":"Una persona in stato di shock va rassicurata e gli indumenti stretti vanno allentati. Non darle alcol e non farla camminare.","source":"Driving school WhatsApp material"},{"id":"SCHOOL.002","category":"Accidents","status":"school_material_confirmed","question":"At an accident, when the area is safe, what should you do first for a casualty who is still inside a dangerous vehicle?","question_it":"Durante un incidente, quando l'area è sicura, cosa devi fare per prima cosa con un ferito ancora in un veicolo pericoloso?","answers":["Get them out only if there is immediate danger","Give them water","Ask them to stand up","Leave without calling for help"],"answers_it":["Estrarlo solo se esiste un pericolo immediato","Dargli acqua","Chiedergli di alzarsi","Andartene senza chiamare aiuto"],"correct":[0],"explanation":"Casualties should normally not be moved, unless there is immediate danger such as fire.","explanation_it":"Normalmente i feriti non vanno spostati, salvo pericolo immediato come un incendio.","source":"Driving school WhatsApp material"},{"id":"SCHOOL.003","category":"Vehicle faults","status":"school_material_confirmed","question":"While driving, the steering suddenly becomes heavy. What could this indicate? Select 2 answers.","question_it":"Durante la guida lo sterzo diventa improvvisamente pesante. Cosa può indicare? Seleziona 2 risposte.","answers":["A puncture in a front tyre","Failure of power-assisted steering","Low washer fluid","A loose seat belt"],"answers_it":["Una foratura a uno pneumatico anteriore","Un guasto al servosterzo","Liquido lavavetri basso","Una cintura allentata"],"correct":[0,1],"explanation":"Heavy steering may be caused by a front tyre puncture or failure of the power-assisted steering.","explanation_it":"Uno sterzo pesante può essere causato da una foratura anteriore o da un guasto al servosterzo.","source":"Driving school WhatsApp material"},{"id":"SCHOOL.004","category":"Mirrors and observation","status":"school_material_confirmed","question":"What should you first check before moving to the right?","question_it":"Cosa devi controllare per prima cosa prima di spostarti a destra?","answers":["The offside driver's mirror","The kerbside mirror only","The rear seat","The fuel gauge"],"answers_it":["Lo specchio esterno lato conducente","Solo lo specchio lato marciapiede","Il sedile posteriore","L'indicatore del carburante"],"correct":[0],"explanation":"Before moving right, first check the offside, or driver's-side, mirror.","explanation_it":"Prima di spostarti a destra controlla per prima cosa lo specchio lato conducente.","source":"Driving school WhatsApp material"},{"id":"SCHOOL.005","category":"Fuel safety","status":"school_material_confirmed","question":"To prevent fuel spillages, it is important to:","question_it":"Per prevenire fuoriuscite di carburante è importante:","answers":["Close and secure all filler caps","Overfill the tank","Leave the cap loose","Refuel with the engine running"],"answers_it":["Chiudere e fissare bene tutti i tappi","Riempire troppo il serbatoio","Lasciare il tappo allentato","Fare rifornimento con il motore acceso"],"correct":[0],"explanation":"All filler caps must be properly closed and secured.","explanation_it":"Tutti i tappi di rifornimento devono essere chiusi e fissati correttamente.","source":"Driving school WhatsApp material"},{"id":"SCHOOL.006","category":"Environment","status":"school_material_confirmed","question":"Vehicles have damaged the environment. What has this resulted in? Select 3 answers.","question_it":"I veicoli hanno danneggiato l'ambiente. Quali conseguenze ne sono derivate? Seleziona 3 risposte.","answers":["Air pollution","Damage to buildings","Using up natural resources","Cleaner air","Less fuel consumption"],"answers_it":["Inquinamento atmosferico","Danni agli edifici","Consumo di risorse naturali","Aria più pulita","Minore consumo di carburante"],"correct":[0,1,2],"explanation":"Road transport contributes to air pollution, damage to buildings and depletion of natural resources.","explanation_it":"Il trasporto stradale contribuisce all'inquinamento, al deterioramento degli edifici e al consumo delle risorse naturali.","source":"Driving school WhatsApp material"},{"id":"SCHOOL.007","category":"Junctions","status":"school_material_confirmed","question":"You want to turn right at a junction marked with two right-turn lanes. There is enough room in either lane. What should you do?","question_it":"Vuoi girare a destra a un incrocio con due corsie di svolta a destra. C'è spazio in entrambe. Cosa devi fare?","answers":["Use the right-hand lane, then move left as you enter the new road","Use the left lane and cut across","Stop in both lanes","Change lanes without checking"],"answers_it":["Usare la corsia destra e poi spostarti a sinistra entrando nella nuova strada","Usare la corsia sinistra e tagliare","Fermarti occupando entrambe le corsie","Cambiare corsia senza controllare"],"correct":[0],"explanation":"Use the right-hand lane and follow the road markings into the correct lane after the turn.","explanation_it":"Usa la corsia destra e segui la segnaletica per entrare nella corsia corretta dopo la svolta.","source":"Driving school WhatsApp material"},{"id":"SCHOOL.008","category":"Engine maintenance","status":"school_material_confirmed","question":"Why should engine oil be changed at the recommended intervals?","question_it":"Perché l'olio motore va sostituito agli intervalli raccomandati?","answers":["To reduce friction and wear","To increase exhaust smoke","To make the brakes harder","To reduce tyre pressure"],"answers_it":["Per ridurre attrito e usura","Per aumentare il fumo di scarico","Per rendere i freni più duri","Per ridurre la pressione degli pneumatici"],"correct":[0],"explanation":"Fresh engine oil lubricates moving parts and reduces friction and wear.","explanation_it":"L'olio nuovo lubrifica le parti mobili e riduce attrito e usura.","source":"Driving school WhatsApp material"},{"id":"SCHOOL.009","category":"Seat belts","status":"school_material_confirmed","question":"You may remove your seat belt when carrying out a manoeuvre that involves:","question_it":"Puoi togliere la cintura di sicurezza quando esegui una manovra che comporta:","answers":["Reversing","Overtaking","Driving through a tunnel","Approaching a junction"],"answers_it":["Retromarcia","Sorpasso","Guida in galleria","Avvicinamento a un incrocio"],"correct":[0],"explanation":"The exemption applies when reversing if the belt restricts the manoeuvre.","explanation_it":"L'esenzione si applica durante la retromarcia se la cintura ostacola la manovra.","source":"Driving school WhatsApp material"},{"id":"SCHOOL.010","category":"Wet weather","status":"school_material_confirmed","question":"In heavy rain, what is the least amount of braking distance you should allow compared with normal?","question_it":"Con pioggia intensa, quale distanza minima di frenata devi lasciare rispetto al normale?","answers":["The same distance","Twice the normal distance","Half the normal distance","Three times the normal distance in every case"],"answers_it":["La stessa distanza","Il doppio della distanza normale","Metà della distanza normale","Sempre tre volte la distanza normale"],"correct":[1],"explanation":"In wet conditions you should allow at least twice the normal distance.","explanation_it":"Sul bagnato devi lasciare almeno il doppio della distanza normale.","source":"Driving school WhatsApp material"},{"id":"SCHOOL.011","category":"ABS","status":"school_material_reviewed","question":"What should you do when braking hard in a vehicle fitted with anti-lock brakes?","question_it":"Cosa devi fare durante una frenata forte con un veicolo dotato di ABS?","answers":["Press the brake firmly and continuously","Pump the brake pedal","Use only the parking brake","Release the brake completely"],"answers_it":["Premere il freno con forza e mantenerlo premuto","Pompare il pedale del freno","Usare solo il freno di stazionamento","Rilasciare completamente il freno"],"correct":[0],"explanation":"With ABS, apply firm continuous pressure. Pumping the pedal can reduce effectiveness.","explanation_it":"Con l'ABS devi premere con forza e in modo continuo. Pompare il pedale può ridurne l'efficacia.","source":"Driving school material corrected against road-safety rule"},{"id":"SCHOOL.012","category":"Emergency braking","status":"school_material_reviewed","question":"In a vehicle without anti-lock brakes, what is most likely to help prevent wheel lock during emergency braking?","question_it":"In un veicolo senza ABS, cosa aiuta maggiormente a prevenire il bloccaggio delle ruote durante una frenata d'emergenza?","answers":["Use controlled threshold braking","Apply the parking brake fully","Turn off the engine","Pump the accelerator"],"answers_it":["Usare una frenata controllata al limite del bloccaggio","Tirare completamente il freno di stazionamento","Spegnere il motore","Pompare l'acceleratore"],"correct":[0],"explanation":"Controlled braking near the point of wheel lock helps retain steering control.","explanation_it":"Una frenata controllata vicino al punto di bloccaggio aiuta a mantenere il controllo dello sterzo.","source":"Driving school material corrected against road-safety rule"},{"id":"SCHOOL.013","category":"Police signals","status":"school_material_confirmed","question":"A police car is following you and wants you to stop. How may the officers signal this?","question_it":"Un'auto della polizia ti segue e vuole che ti fermi. Come può segnalartelo?","answers":["By flashing headlights and activating blue lights or other clear police signals","By sounding the horn only","By overtaking without signalling","By turning off all lights"],"answers_it":["Lampeggiando e attivando luci blu o altri segnali chiari della polizia","Solo suonando il clacson","Sorpassando senza segnalare","Spegnendo tutte le luci"],"correct":[0],"explanation":"Comply with clear police instructions and stop safely as soon as possible.","explanation_it":"Rispetta i segnali chiari della polizia e fermati in sicurezza appena possibile.","source":"Driving school WhatsApp material"},{"id":"SCHOOL.014","category":"Insurance","status":"school_material_reviewed","question":"A conviction for driving while unfit through drink or drugs is most likely to increase the cost of:","question_it":"Una condanna per guida in stato di alterazione da alcol o droghe farà probabilmente aumentare il costo di:","answers":["Vehicle insurance","Driving licence renewal","Fuel","VRT testing"],"answers_it":["Assicurazione del veicolo","Rinnovo della patente","Carburante","Controllo VRT"],"correct":[0],"explanation":"Such convictions usually result in substantially higher motor-insurance premiums.","explanation_it":"Una simile condanna comporta normalmente un forte aumento del premio assicurativo.","source":"Driving school material corrected"},{"id":"SCHOOL.015","category":"Cyclists","status":"school_material_confirmed","question":"You should never attempt to overtake a cyclist:","question_it":"Non devi mai tentare di sorpassare un ciclista:","answers":["On a roundabout","On a straight road with plenty of room","At low speed with a wide gap","When the road ahead is completely clear"],"answers_it":["In una rotatoria","Su un rettilineo con molto spazio","A bassa velocità lasciando ampio spazio","Quando la strada davanti è completamente libera"],"correct":[0],"explanation":"Do not overtake cyclists on a roundabout because their line and direction may change.","explanation_it":"Non sorpassare i ciclisti in rotatoria perché la loro traiettoria e direzione possono cambiare.","source":"Driving school WhatsApp material"},{"id":"SCHOOL.016","category":"Motorcyclists","status":"school_material_confirmed","question":"You intend to turn right into a side road. Just before turning, you should check for motorcyclists who might be:","question_it":"Vuoi girare a destra in una strada laterale. Subito prima di svoltare devi controllare la presenza di motociclisti che potrebbero:","answers":["Overtaking on your right","Parked on the pavement","Following far behind","Turning left behind you"],"answers_it":["Sorpassarti sulla destra","Essere parcheggiati sul marciapiede","Seguirti molto lontano","Girare a sinistra dietro di te"],"correct":[0],"explanation":"A motorcyclist may be overtaking on your right and hidden in your blind spot.","explanation_it":"Un motociclista potrebbe sorpassarti a destra ed essere nascosto nell'angolo cieco.","source":"Driving school WhatsApp material"},{"id":"SCHOOL.017","category":"Country roads","status":"school_material_confirmed","question":"On a country road, what should you expect to see coming towards you on your side of the road?","question_it":"Su una strada di campagna, cosa potresti vedere arrivare verso di te sul tuo lato della strada?","answers":["Horse riders","Only parked cars","Traffic lights","Pedestrian barriers"],"answers_it":["Cavalieri","Solo auto parcheggiate","Semafori","Barriere pedonali"],"correct":[0],"explanation":"Horse riders may use the road and may be positioned away from the edge for safety.","explanation_it":"I cavalieri possono usare la strada e posizionarsi lontano dal bordo per sicurezza.","source":"Driving school WhatsApp material"},{"id":"SCHOOL.018","category":"Mobile phones","status":"school_material_confirmed","question":"Using a hands-free phone while driving is likely to:","question_it":"Usare un telefono vivavoce durante la guida può:","answers":["Divert your attention","Improve concentration","Shorten stopping distance","Make steering lighter"],"answers_it":["Distogliere la tua attenzione","Migliorare la concentrazione","Ridurre la distanza di arresto","Rendere lo sterzo più leggero"],"correct":[0],"explanation":"Hands-free calls still create mental distraction.","explanation_it":"Le chiamate in vivavoce creano comunque distrazione mentale.","source":"Driving school WhatsApp material"},{"id":"SCHOOL.019","category":"Motorcyclists","status":"school_material_confirmed","question":"Why should you allow extra room to motorcyclists riding through roadworks?","question_it":"Perché devi lasciare più spazio ai motociclisti che attraversano lavori stradali?","answers":["They may swerve to avoid potholes","They always travel faster","They cannot use their brakes","They must ride in the centre"],"answers_it":["Possono deviare per evitare buche","Viaggiano sempre più velocemente","Non possono usare i freni","Devono stare al centro"],"correct":[0],"explanation":"Motorcyclists may need to change direction suddenly to avoid potholes or loose surfaces.","explanation_it":"I motociclisti possono dover cambiare direzione improvvisamente per evitare buche o fondo sconnesso.","source":"Driving school WhatsApp material"},{"id":"SCHOOL.020","category":"Vehicle emissions","status":"school_material_confirmed","question":"You are driving a vehicle with excessive exhaust smoke. Which statement is correct?","question_it":"Stai guidando un veicolo con fumo di scarico eccessivo. Quale affermazione è corretta?","answers":["You may be breaking the law","It is acceptable on short journeys","It only affects fuel economy","It is safe if the engine is warm"],"answers_it":["Potresti violare la legge","È accettabile nei tragitti brevi","Influisce solo sul consumo","È sicuro se il motore è caldo"],"correct":[0],"explanation":"Excessive exhaust smoke may indicate a defect and can be an offence.","explanation_it":"Il fumo eccessivo può indicare un guasto e costituire un'infrazione.","source":"Driving school WhatsApp material"},{"id":"CUSTOMER.001","category":"Customer care","status":"training_variant_verified_rule","question":"A passenger refuses to pay the agreed fare. What should you do first?","question_it":"Un passeggero rifiuta di pagare la tariffa concordata. Cosa devi fare per prima cosa?","answers":["Remain calm and follow the operator's procedure","Lock the passenger in the vehicle","Use physical force","Drive away with the passenger's luggage"],"answers_it":["Restare calmo e seguire la procedura dell'operatore","Chiudere il passeggero nel veicolo","Usare la forza fisica","Andartene con i bagagli del passeggero"],"correct":[0],"explanation":"Remain professional, avoid confrontation and follow the operator's or police-reporting procedure.","explanation_it":"Mantieni un comportamento professionale, evita lo scontro e segui la procedura dell'operatore o della polizia.","source":"Training variant based on school material"},{"id":"CUSTOMER.002","category":"Customer care","status":"training_variant_verified_rule","question":"A family asks you to exceed the speed limit because they are late for the airport. What should you do?","question_it":"Una famiglia ti chiede di superare il limite perché è in ritardo per l'aeroporto. Cosa devi fare?","answers":["Obey the speed limit and drive safely","Speed only on clear roads","Ask for extra payment and speed up","Use hazard lights and exceed the limit"],"answers_it":["Rispettare il limite e guidare in sicurezza","Superare il limite solo su strade libere","Chiedere un supplemento e accelerare","Usare le quattro frecce e superare il limite"],"correct":[0],"explanation":"Passenger urgency never justifies breaking the speed limit.","explanation_it":"L'urgenza del passeggero non giustifica mai il superamento del limite.","source":"School sheet material"},{"id":"CUSTOMER.003","category":"Vulnerable passengers","status":"training_variant_verified_rule","question":"When carrying a vulnerable passenger, what should you do? Select 2 answers.","question_it":"Quando trasporti un passeggero vulnerabile, cosa devi fare? Seleziona 2 risposte.","answers":["Drive smoothly","Offer appropriate assistance","Brake harshly to save time","Discuss the passenger's condition with strangers"],"answers_it":["Guidare dolcemente","Offrire assistenza adeguata","Frenare bruscamente per risparmiare tempo","Parlare della condizione del passeggero con estranei"],"correct":[0,1],"explanation":"Provide a smooth journey and suitable assistance while respecting dignity and privacy.","explanation_it":"Offri un viaggio regolare e assistenza adeguata, rispettando dignità e riservatezza.","source":"Training variant based on LPTV customer-care principles"},{"id":"CUSTOMER.004","category":"Disabled passengers","status":"training_variant_verified_rule","question":"A disabled passenger says that they do not need help. What should you do?","question_it":"Un passeggero con disabilità dice di non aver bisogno di aiuto. Cosa devi fare?","answers":["Respect their decision but remain ready to assist","Insist on helping physically","Refuse the journey","Ignore all future requests"],"answers_it":["Rispettare la decisione ma restare disponibile ad aiutare","Insistere per aiutarlo fisicamente","Rifiutare la corsa","Ignorare ogni richiesta successiva"],"correct":[0],"explanation":"Respect the passenger's independence while remaining available if help is later requested.","explanation_it":"Rispetta l'autonomia del passeggero, restando disponibile se successivamente chiede aiuto.","source":"Training variant based on customer-care principles"},{"id":"CUSTOMER.005","category":"Passenger comfort","status":"training_variant_verified_rule","question":"For the safety and comfort of passengers, which actions are appropriate? Select 3 answers.","question_it":"Per la sicurezza e il comfort dei passeggeri, quali azioni sono corrette? Seleziona 3 risposte.","answers":["Brake smoothly","Think well ahead","Stop close to the kerb where safe","Give change while the vehicle is moving","Accelerate sharply"],"answers_it":["Frenare dolcemente","Pensare e pianificare in anticipo","Fermarsi vicino al marciapiede quando è sicuro","Dare il resto mentre il veicolo è in movimento","Accelerare bruscamente"],"correct":[0,1,2],"explanation":"Smooth driving, anticipation and safe kerbside stopping improve passenger safety and comfort.","explanation_it":"Guida fluida, previsione e fermata sicura vicino al marciapiede migliorano sicurezza e comfort.","source":"School sheet material corrected"},{"id":"CARS13.4","category":"Accidents","status":"official_transport_malta","question":"You arrive at the scene of a motorcycle accident. The rider is injured. When should the helmet be removed?","question_it":"Arrivi sul luogo di un incidente motociclistico. Il motociclista è ferito. Quando va rimosso il casco?","answers":["Only when it is essential","Always unless the rider is in shock","Only when the motorcyclist asks","Always straight away"],"answers_it":["Solo quando è indispensabile","Sempre, salvo stato di shock","Solo se lo chiede il motociclista","Sempre immediatamente"],"correct":[0],"explanation":"A motorcycle helmet should only be removed when it is essential, for example to maintain an airway.","explanation_it":"Il casco va rimosso solo quando è indispensabile, per esempio per mantenere libere le vie aeree.","source":"Transport Malta Cars Version 4"},{"id":"CARS13.5","category":"Accidents","status":"official_transport_malta","question":"You arrive at a serious motorcycle accident. The motorcyclist is unconscious and bleeding. What are your main priorities? Select 3 answers.","question_it":"Arrivi a un grave incidente motociclistico. Il motociclista è incosciente e sanguina. Quali sono le priorità principali? Seleziona 3 risposte.","answers":["Check the casualty's breathing","Try to stop any bleeding","Sweep up loose debris","Take vehicle registration numbers","Check that the airway is clear","Make a list of witnesses"],"answers_it":["Controllare la respirazione","Cercare di fermare l'emorragia","Raccogliere i detriti","Annotare le targhe","Controllare che le vie aeree siano libere","Fare un elenco dei testimoni"],"correct":[0,1,4],"explanation":"The immediate priorities are airway, breathing and severe bleeding.","explanation_it":"Le priorità immediate sono vie aeree, respirazione ed emorragie gravi.","source":"Transport Malta Cars Version 4"},{"id":"CARS13.6","category":"Accidents","status":"official_transport_malta","question":"You arrive at an accident. A motorcyclist is unconscious. What is your first priority?","question_it":"Arrivi a un incidente. Un motociclista è incosciente. Qual è la prima priorità?","answers":["Breathing","Bruising","Broken bones","Bleeding"],"answers_it":["Respirazione","Lividi","Fratture","Emorragia"],"correct":[0],"explanation":"Breathing must be checked immediately.","explanation_it":"La respirazione deve essere controllata immediatamente.","source":"Transport Malta Cars Version 4"},{"id":"CARS13.7","category":"Accidents","status":"official_transport_malta","question":"At an accident a casualty is unconscious. Which three things should you check urgently?","question_it":"Durante un incidente un ferito è incosciente. Quali tre cose devi controllare urgentemente?","answers":["Broken bones","Airway","Shock","Circulation","Breathing"],"answers_it":["Fratture","Vie aeree","Shock","Circolazione","Respirazione"],"correct":[1,3,4],"explanation":"Urgent checks follow the ABC principle: airway, breathing and circulation.","explanation_it":"I controlli urgenti seguono il principio ABC: vie aeree, respirazione e circolazione.","source":"Transport Malta Cars Version 4"},{"id":"CARS13.8","category":"Accidents","status":"official_transport_malta","question":"In first aid, what does ABC stand for? Select 3 answers.","question_it":"Nel primo soccorso, cosa significa ABC? Seleziona 3 risposte.","answers":["Circulation","Airway","Bleeding","Alert","Breathing","Conscious"],"answers_it":["Circolazione","Vie aeree","Emorragia","Allerta","Respirazione","Coscienza"],"correct":[0,1,4],"explanation":"ABC stands for Airway, Breathing and Circulation.","explanation_it":"ABC significa vie aeree, respirazione e circolazione.","source":"Transport Malta Cars Version 4"},{"id":"CARS13.9","category":"Accidents","status":"official_transport_malta","question":"At an accident someone is unconscious. What are your main priorities? Select 3 answers.","question_it":"Durante un incidente una persona è incosciente. Quali sono le priorità principali? Seleziona 3 risposte.","answers":["Make sure they are breathing","Check that the airway is clear","Stop any heavy bleeding","Count the vehicles involved","Take witness names","Sweep up broken glass"],"answers_it":["Assicurarsi che respiri","Controllare che le vie aeree siano libere","Fermare eventuali emorragie gravi","Contare i veicoli coinvolti","Prendere i nomi dei testimoni","Raccogliere i vetri"],"correct":[0,1,2],"explanation":"Airway, breathing and severe bleeding take priority.","explanation_it":"Vie aeree, respirazione ed emorragie gravi hanno la priorità.","source":"Transport Malta Cars Version 4"},{"id":"CARS13.11","category":"Accidents","status":"official_transport_malta","question":"There has been an accident. The driver is suffering from shock. What should you do? Select 2 answers.","question_it":"C'è stato un incidente. Il conducente è in stato di shock. Cosa devi fare? Seleziona 2 risposte.","answers":["Do not leave the driver alone","Reassure the driver","Ask who caused the accident","Offer a cigarette","Give a drink"],"answers_it":["Non lasciare solo il conducente","Rassicurare il conducente","Chiedere chi ha causato l'incidente","Offrire una sigaretta","Dare da bere"],"correct":[0,1],"explanation":"Stay with the casualty and reassure them.","explanation_it":"Resta con il ferito e rassicuralo.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.19","category":"Vulnerable road users","status":"official_transport_malta","question":"If you are following a car driven by an elderly driver, what should you remember?","question_it":"Se segui un'auto guidata da una persona anziana, cosa devi ricordare?","answers":["Stay close behind","Flash your lights and overtake","The driver's reactions may not be as fast as yours","Expect the driver to drive badly"],"answers_it":["Restare molto vicino","Lampeggiare e sorpassare","Le reazioni del conducente potrebbero essere più lente delle tue","Aspettarti che guidi male"],"correct":[2],"explanation":"Allow extra time and space because reactions may be slower.","explanation_it":"Lascia più tempo e spazio perché le reazioni potrebbero essere più lente.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.22","category":"Vulnerable road users","status":"official_transport_malta","question":"If you see a pedestrian carrying a white stick, what does this show?","question_it":"Se vedi un pedone con un bastone bianco, cosa indica?","answers":["The person is elderly","The person is deaf","The person is disabled","The person is blind"],"answers_it":["La persona è anziana","La persona è sorda","La persona è disabile","La persona è cieca"],"correct":[3],"explanation":"A white stick indicates that the pedestrian is blind.","explanation_it":"Il bastone bianco indica che il pedone è cieco.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.23","category":"Vulnerable road users","status":"official_transport_malta","question":"You are driving towards a zebra crossing. A person in a wheelchair is waiting to cross. What should you do?","question_it":"Stai guidando verso un attraversamento zebra. Una persona in sedia a rotelle aspetta di attraversare. Cosa devi fare?","answers":["Wave to the person to wait","Wave to the person to cross","Continue on your way","Be prepared to stop"],"answers_it":["Fare cenno di aspettare","Fare cenno di attraversare","Proseguire","Prepararti a fermarti"],"correct":[3],"explanation":"Approach carefully and be prepared to stop.","explanation_it":"Avvicinati con cautela e preparati a fermarti.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.24","category":"Vulnerable road users","status":"official_transport_malta","question":"What should you do when elderly people are crossing the road?","question_it":"Cosa devi fare quando persone anziane attraversano la strada?","answers":["Tap the horn","Be patient and allow them to cross in their own time","Rev the engine","Wave them across"],"answers_it":["Suonare leggermente il clacson","Essere paziente e lasciarle attraversare con i loro tempi","Accelerare il motore","Fare cenno di attraversare"],"correct":[1],"explanation":"Be patient and do not pressure vulnerable pedestrians.","explanation_it":"Sii paziente e non mettere fretta ai pedoni vulnerabili.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.27","category":"Cyclists","status":"official_transport_malta","question":"You should never attempt to overtake a cyclist:","question_it":"Non devi mai tentare di sorpassare un ciclista:","answers":["Just before you turn left","On a dual carriageway","On a one-way street","Just before you turn right"],"answers_it":["Subito prima di girare a sinistra","Su una strada a doppia carreggiata","In una strada a senso unico","Subito prima di girare a destra"],"correct":[0],"explanation":"Overtaking before a left turn risks cutting across the cyclist.","explanation_it":"Sorpassare prima di svoltare a sinistra rischia di tagliare la strada al ciclista.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.28","category":"Cyclists","status":"official_transport_malta","question":"You are driving behind a cyclist and intend to turn left just ahead. What should you do?","question_it":"Guidi dietro a un ciclista e devi girare a sinistra poco più avanti. Cosa devi fare?","answers":["Go around the cyclist at the junction","Pull alongside and stay level","Hold back until the cyclist has passed the junction","Overtake before the junction"],"answers_it":["Superare il ciclista all'incrocio","Affiancarlo e restare alla stessa altezza","Restare dietro finché il ciclista non ha superato l'incrocio","Sorpassarlo prima dell'incrocio"],"correct":[2],"explanation":"Do not cut across the cyclist; wait behind.","explanation_it":"Non tagliare la strada al ciclista; resta dietro.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.29","category":"Cyclists","status":"official_transport_malta","question":"You are approaching a roundabout and a cyclist is signalling right. What should you do?","question_it":"Ti avvicini a una rotatoria e un ciclista segnala a destra. Cosa devi fare?","answers":["Signal the cyclist to move across","Sound the horn","Overtake on the right","Give the cyclist plenty of room"],"answers_it":["Fare cenno al ciclista di spostarsi","Suonare il clacson","Sorpassare a destra","Lasciare molto spazio al ciclista"],"correct":[3],"explanation":"Cyclists need extra room and may change position for safety.","explanation_it":"I ciclisti hanno bisogno di più spazio e possono cambiare posizione per sicurezza.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.30","category":"Cyclists","status":"official_transport_malta","question":"Three cyclists approach a roundabout in the left-hand lane. In which direction should you expect them to go?","question_it":"Tre ciclisti si avvicinano a una rotatoria nella corsia sinistra. In quale direzione devi aspettarti che vadano?","answers":["Straight ahead","Right","Any direction","Left"],"answers_it":["Dritto","A destra","In qualsiasi direzione","A sinistra"],"correct":[2],"explanation":"Cyclists may stay left for safety even when taking another exit.","explanation_it":"I ciclisti possono restare a sinistra per sicurezza anche se prendono un'altra uscita.","source":"Transport Malta Cars Version 4"},{"id":"CARS10.5","category":"Road signs","status":"official_transport_malta","question":"You see a 30 kph maximum speed sign ahead. What does it mean?","question_it":"Vedi davanti un segnale di limite massimo di 30 km/h. Cosa significa?","answers":["The minimum speed is 30 kph","You are leaving a 30 kph zone","Slow to 30 kph only after passing","Do not exceed 30 kph after passing"],"answers_it":["La velocità minima è 30 km/h","Stai uscendo da una zona 30","Rallenta a 30 solo dopo averlo superato","Non superare 30 km/h dopo il segnale"],"correct":[3],"explanation":"The limit applies from the sign onward.","explanation_it":"Il limite si applica dal segnale in poi.","source":"Transport Malta Cars Version 4"},{"id":"CARS11.7","category":"Road signs","status":"official_transport_malta","question":"What does the end of 20 kph zone sign mean?","question_it":"Cosa significa il segnale di fine zona 20 km/h?","answers":["Minimum speed 30 kph","No vehicles over 30 tonnes","New speed limit 20 kph","End of 20 kph zone"],"answers_it":["Velocità minima 30 km/h","Divieto ai veicoli oltre 30 tonnellate","Nuovo limite 20 km/h","Fine della zona 20 km/h"],"correct":[3],"explanation":"The sign marks the end of the 20 kph zone.","explanation_it":"Il segnale indica la fine della zona con limite 20 km/h.","source":"Transport Malta Cars Version 4"},{"id":"CARS11.8","category":"Road signs","status":"official_transport_malta","question":"What does the no motor vehicles sign mean?","question_it":"Cosa significa il segnale di divieto ai veicoli a motore?","answers":["No motor vehicles","Cars and motorcycles only","Clearway","No overtaking"],"answers_it":["Divieto ai veicoli a motore","Solo auto e moto","Strada libera senza fermata","Divieto di sorpasso"],"correct":[0],"explanation":"Motor vehicles are prohibited beyond the sign.","explanation_it":"I veicoli a motore sono vietati oltre il segnale.","source":"Transport Malta Cars Version 4"},{"id":"CARS11.9","category":"Road signs","status":"official_transport_malta","question":"What does a no-entry sign mean?","question_it":"Cosa significa il segnale di divieto di accesso?","answers":["No through road","No road markings","No parking","No entry"],"answers_it":["Strada senza uscita","Assenza di segnaletica","Divieto di sosta","Divieto di accesso"],"correct":[3],"explanation":"Vehicles must not enter from that direction.","explanation_it":"I veicoli non devono entrare da quella direzione.","source":"Transport Malta Cars Version 4"},{"id":"CARS11.10","category":"Road signs","status":"official_transport_malta","question":"What does a no-right-turn sign mean?","question_it":"Cosa significa il segnale di divieto di svolta a destra?","answers":["No traffic from the right","Road on the right closed","Bend on the right","No right turn"],"answers_it":["Nessun traffico da destra","Strada a destra chiusa","Curva a destra","Divieto di svolta a destra"],"correct":[3],"explanation":"Turning right is prohibited.","explanation_it":"La svolta a destra è vietata.","source":"Transport Malta Cars Version 4"},{"id":"CARS10.21","category":"Rules of the road","status":"official_transport_malta","question":"You are approaching a busy junction. There are several lanes with road markings. At the last moment you realise that you are in the wrong lane. What should you do?","question_it":"Ti avvicini a un incrocio trafficato con più corsie e segnaletica orizzontale. All'ultimo momento ti accorgi di essere nella corsia sbagliata. Cosa devi fare?","answers":["Continue in that lane","Use clear arm signals to cut across","Stop until the area has cleared","Force your way across"],"answers_it":["Continuare in quella corsia","Usare segnali con il braccio per tagliare le corsie","Fermarti finché l'area non è libera","Forzare il passaggio attraversando le corsie"],"correct":[0],"explanation":"Do not make a sudden or unsafe lane change. Continue in the lane and correct your route later.","explanation_it":"Non effettuare un cambio di corsia improvviso o pericoloso. Continua in quella corsia e correggi il percorso più avanti.","source":"Transport Malta Cars Version 4"},{"id":"CARS10.22","category":"Overtaking","status":"official_transport_malta","question":"Where may you overtake on a one-way street?","question_it":"Dove puoi sorpassare in una strada a senso unico?","answers":["Only on the right-hand side","Overtaking is not allowed","Only on the left-hand side","Either on the right or the left"],"answers_it":["Solo sul lato destro","Il sorpasso non è consentito","Solo sul lato sinistro","Sia a destra sia a sinistra"],"correct":[3],"explanation":"On a one-way street, overtaking may be carried out on either side when it is safe and lawful.","explanation_it":"In una strada a senso unico il sorpasso può essere effettuato su entrambi i lati quando è sicuro e consentito.","source":"Transport Malta Cars Version 4"},{"id":"CARS10.23","category":"Single-track roads","status":"official_transport_malta","question":"You are driving on a single-track road with passing places only on the right. The driver behind wishes to overtake. What should you do?","question_it":"Guidi su una strada a corsia unica con piazzole di scambio solo a destra. Il conducente dietro vuole sorpassare. Cosa devi fare?","answers":["Drive into a passing place on your right","Switch on your hazard warning lights","Wait opposite a passing place on your right","Speed up to get away"],"answers_it":["Entrare nella piazzola a destra","Accendere le quattro frecce","Fermarti di fronte a una piazzola sulla destra","Accelerare per allontanarti"],"correct":[2],"explanation":"Wait opposite the passing place so the following vehicle can use it to overtake safely.","explanation_it":"Fermati di fronte alla piazzola così il veicolo che segue può usarla per sorpassare in sicurezza.","source":"Transport Malta Cars Version 4"},{"id":"CARS10.24","category":"Single-track roads","status":"official_transport_malta","question":"You are on a road that is only wide enough for one vehicle. A car is coming towards you. Which TWO actions are correct?","question_it":"Sei su una strada larga quanto un solo veicolo e un'auto arriva in senso opposto. Quali DUE azioni sono corrette?","answers":["Wait opposite a passing place on your left","Pull into a passing place if your vehicle is wider","Force the other driver to reverse","Wait opposite a passing place on your right","Pull into a passing place on your left","Pull into a passing place on your right"],"answers_it":["Fermarti di fronte a una piazzola sulla sinistra","Entrare in una piazzola se il tuo veicolo è più largo","Costringere l'altro conducente a fare retromarcia","Fermarti di fronte a una piazzola sulla destra","Entrare in una piazzola sulla sinistra","Entrare in una piazzola sulla destra"],"correct":[3,4],"explanation":"Use a passing place on your left, or wait opposite one on your right so the oncoming vehicle can enter it.","explanation_it":"Usa una piazzola sulla tua sinistra oppure fermati di fronte a una piazzola sulla destra, così il veicolo in arrivo può entrarvi.","source":"Transport Malta Cars Version 4"},{"id":"CARS10.25","category":"Signals","status":"official_transport_malta","question":"Signals are normally given by direction indicators and:","question_it":"I segnali vengono normalmente dati con gli indicatori di direzione e:","answers":["Brake lights","Interior lights","Fog lights","Side lights"],"answers_it":["Luci dei freni","Luci interne","Fendinebbia","Luci di posizione"],"correct":[0],"explanation":"Brake lights communicate that you are slowing or stopping.","explanation_it":"Le luci dei freni comunicano che stai rallentando o fermandoti.","source":"Transport Malta Cars Version 4"},{"id":"CARS10.26","category":"Roundabouts","status":"official_transport_malta","question":"When going straight ahead at a roundabout, when should you indicate left?","question_it":"Quando prosegui dritto a una rotatoria, quando devi mettere l'indicatore sinistro?","answers":["Just after passing the exit before the one you will take","When approaching the roundabout","Indicate right when approaching","Do not indicate at any time"],"answers_it":["Subito dopo aver superato l'uscita precedente a quella che prenderai","Avvicinandoti alla rotatoria","Indicare a destra avvicinandoti","Non indicare mai"],"correct":[0],"explanation":"Signal left after passing the exit immediately before your intended exit.","explanation_it":"Metti l'indicatore sinistro dopo aver superato l'uscita immediatamente precedente alla tua.","source":"Transport Malta Cars Version 4"},{"id":"CARS10.27","category":"Roundabouts","status":"official_transport_malta","question":"Which vehicle might have to use a different course from normal at a roundabout?","question_it":"Quale veicolo potrebbe dover seguire una traiettoria diversa dal normale in una rotatoria?","answers":["Estate car","Van","Sports car","Long vehicle"],"answers_it":["Station wagon","Furgone","Auto sportiva","Veicolo lungo"],"correct":[3],"explanation":"Long vehicles may need extra road space and a wider path through a roundabout.","explanation_it":"I veicoli lunghi possono aver bisogno di più spazio e di una traiettoria più ampia in rotatoria.","source":"Transport Malta Cars Version 4"},{"id":"CARS12.9","category":"Documents and penalty points","status":"official_transport_malta","question":"What maximum number of penalty points automatically disqualifies a driver holding a probationary driving licence?","question_it":"Quale numero massimo di punti di penalità comporta automaticamente la squalifica di un conducente con patente in prova?","answers":["4 points a year over 3 years","12 points at any time during a 3-year period","18 points over 2 years","10 points during one year","15 points over 5 years"],"answers_it":["4 punti all'anno per 3 anni","12 punti in qualsiasi momento durante un periodo di 3 anni","18 punti in 2 anni","10 punti in un anno","15 punti in 5 anni"],"correct":[1],"explanation":"A probationary driver is automatically disqualified upon reaching 12 points during the three-year probationary period.","explanation_it":"Un conducente in prova viene squalificato automaticamente al raggiungimento di 12 punti durante i tre anni di prova.","source":"Transport Malta Cars Version 4"},{"id":"CARS12.10","category":"Documents and disqualification","status":"official_transport_malta","question":"After complying with any legal punishment, what must a disqualified driver do to obtain a driving licence again?","question_it":"Dopo aver scontato le sanzioni previste, cosa deve fare un conducente squalificato per riottenere la patente?","answers":["Only retake the practical test","Reapply after the disqualification and take only the theory test","Pay outstanding fines, submit a new application after the disqualification period, and pass both theory and practical tests","Wait for the period to end and request a duplicate licence"],"answers_it":["Ripetere solo l'esame pratico","Presentare domanda e sostenere solo la teoria","Pagare le multe pendenti, presentare una nuova domanda dopo la squalifica e superare teoria e pratica","Attendere la fine e chiedere un duplicato"],"correct":[2],"explanation":"The official question requires payment of outstanding fines, a new application and passing both tests after the disqualification period.","explanation_it":"La domanda ufficiale richiede il pagamento delle multe pendenti, una nuova domanda e il superamento di entrambi gli esami dopo la squalifica.","source":"Transport Malta Cars Version 4"},{"id":"CARS5.12","category":"Alcohol","status":"official_transport_malta","question":"After drinking alcohol heavily, why should you not drive the following day? Select 2 answers.","question_it":"Dopo aver bevuto molto alcol, perché non devi guidare il giorno seguente? Seleziona 2 risposte.","answers":["Your concentration may still be badly affected","You may still be over the legal limit","You will be well under the legal limit","Your concentration will not be affected"],"answers_it":["La concentrazione potrebbe essere ancora compromessa","Potresti essere ancora oltre il limite legale","Sarai sicuramente sotto il limite","La concentrazione non sarà compromessa"],"correct":[0,1],"explanation":"Alcohol can remain in the body for many hours, affecting concentration and possibly keeping you over the legal limit.","explanation_it":"L'alcol può restare nel corpo per molte ore, riducendo la concentrazione e lasciandoti eventualmente oltre il limite legale.","source":"Transport Malta Cars Version 4"},{"id":"CARS5.13","category":"Alcohol","status":"official_transport_malta","question":"What advice should you give to a driver who has had a few alcoholic drinks at a party?","question_it":"Che consiglio devi dare a un conducente che ha bevuto alcuni alcolici a una festa?","answers":["Wait a short while and drive home","Drive home slowly","Go home by public transport","Drink strong coffee and drive"],"answers_it":["Aspettare poco e guidare","Guidare lentamente","Tornare con il trasporto pubblico","Bere caffè forte e guidare"],"correct":[2],"explanation":"The safe choice is not to drive and to use another form of transport.","explanation_it":"La scelta sicura è non guidare e usare un altro mezzo di trasporto.","source":"Transport Malta Cars Version 4"},{"id":"CARS5.14","category":"Alcohol","status":"official_transport_malta","question":"You are going to a social event and need to drive shortly afterwards. What precaution should you take?","question_it":"Vai a un evento sociale e devi guidare poco dopo. Quale precauzione devi prendere?","answers":["Drink milk before alcohol","Drink coffee after alcohol","Avoid alcohol completely","Avoid drinking on an empty stomach"],"answers_it":["Bere latte prima dell'alcol","Bere caffè dopo l'alcol","Evitare completamente l'alcol","Non bere a stomaco vuoto"],"correct":[2],"explanation":"If you need to drive, the safest choice is to avoid alcohol completely.","explanation_it":"Se devi guidare, la scelta più sicura è evitare completamente l'alcol.","source":"Transport Malta Cars Version 4"},{"id":"CARS5.15","category":"Alcohol","status":"official_transport_malta","question":"It is eight hours since your last alcoholic drink. Which TWO statements may still apply?","question_it":"Sono passate otto ore dall'ultimo alcolico. Quali DUE affermazioni possono essere ancora vere?","answers":["You will have no alcohol in your system","You will certainly be under the legal limit","You may still be unfit to drive","You may still be over the legal limit"],"answers_it":["Non avrai più alcol nel corpo","Sarai certamente sotto il limite","Potresti essere ancora non idoneo a guidare","Potresti essere ancora oltre il limite"],"correct":[2,3],"explanation":"Eight hours does not guarantee that you are fit to drive or below the legal limit.","explanation_it":"Otto ore non garantiscono che tu sia idoneo a guidare o sotto il limite legale.","source":"Transport Malta Cars Version 4"},{"id":"CARS5.16","category":"Medicines","status":"official_transport_malta","question":"Your doctor has prescribed medicine. Why should you ask whether it is safe to drive?","question_it":"Il medico ti ha prescritto un farmaco. Perché devi chiedere se puoi guidare?","answers":["It may affect your hearing only","Your insurer must always be informed","Some medicines can slow your reactions","Medicines always improve reactions"],"answers_it":["Può influire solo sull'udito","Devi sempre avvisare l'assicurazione","Alcuni farmaci possono rallentare le reazioni","I farmaci migliorano sempre le reazioni"],"correct":[2],"explanation":"Some medicines cause drowsiness or slower reactions.","explanation_it":"Alcuni farmaci provocano sonnolenza o rallentano le reazioni.","source":"Transport Malta Cars Version 4"},{"id":"CARS5.17","category":"Medicines","status":"official_transport_malta","question":"A medicine made you drowsy for several days. You feel better today but still need to take it. When should you drive?","question_it":"Un farmaco ti ha provocato sonnolenza per diversi giorni. Oggi stai meglio ma devi ancora assumerlo. Quando devi guidare?","answers":["If someone travels with you","Only at night","Only if the journey is necessary","After checking with your doctor"],"answers_it":["Se qualcuno viaggia con te","Solo di notte","Solo se il viaggio è necessario","Dopo aver consultato il medico"],"correct":[3],"explanation":"Check with your doctor before driving while taking medicine that caused drowsiness.","explanation_it":"Consulta il medico prima di guidare mentre assumi un farmaco che ha causato sonnolenza.","source":"Transport Malta Cars Version 4"},{"id":"CARS5.18","category":"Medicines","status":"official_transport_malta","question":"A doctor prescribes medicine likely to affect your driving. What should you do?","question_it":"Il medico prescrive un farmaco che può influire sulla guida. Cosa devi fare?","answers":["Never exceed 30 kph","Drive only with a passenger","Do not drive yourself","Avoid only busy roads"],"answers_it":["Non superare mai 30 km/h","Guidare solo con un passeggero","Non guidare personalmente","Evitare soltanto le strade trafficate"],"correct":[2],"explanation":"Do not drive when medicine is likely to impair your driving ability.","explanation_it":"Non guidare quando il farmaco può compromettere la capacità di guida.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.2","category":"Vulnerable road users","status":"official_transport_malta","question":"Which warning sign means that people may be walking along the road?","question_it":"Quale segnale di pericolo indica che potrebbero esserci persone che camminano lungo la strada?","answers":["Pedestrians in the road","No pedestrians","Pedestrian zone ends","School parking only"],"answers_it":["Pedoni sulla strada","Divieto ai pedoni","Fine zona pedonale","Solo parcheggio scolastico"],"correct":[0],"explanation":"The pedestrian warning sign indicates that people may be walking in or alongside the road.","explanation_it":"Il segnale di pericolo pedoni indica che persone potrebbero camminare sulla strada o lungo il bordo.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.4","category":"Pedestrians","status":"official_transport_malta","question":"You are turning left into a side road and pedestrians are crossing. What must you do?","question_it":"Stai girando a sinistra in una strada laterale e dei pedoni stanno attraversando. Cosa devi fare?","answers":["Use hazard lights","Sound the horn","Wave them on","Wait for them to cross"],"answers_it":["Usare le quattro frecce","Suonare il clacson","Fare cenno di passare","Aspettare che attraversino"],"correct":[3],"explanation":"Give way and wait until pedestrians have crossed safely.","explanation_it":"Dai precedenza e attendi che i pedoni abbiano attraversato in sicurezza.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.5","category":"Pedestrians","status":"official_transport_malta","question":"You are turning left at a junction and pedestrians suddenly start crossing. What should you do?","question_it":"Stai girando a sinistra a un incrocio e dei pedoni iniziano improvvisamente ad attraversare. Cosa devi fare?","answers":["Sound the horn and proceed","Stop and wave them across","Continue while leaving room","Give way to them"],"answers_it":["Suonare e proseguire","Fermarti e fare cenno","Continuare lasciando spazio","Dare loro precedenza"],"correct":[3],"explanation":"Pedestrians already crossing have priority; give way.","explanation_it":"I pedoni già in attraversamento hanno la precedenza; devi lasciarli passare.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.10","category":"Junctions","status":"official_transport_malta","question":"Your view from a junction is restricted by parked vehicles. What should you do?","question_it":"La visuale da un incrocio è limitata da veicoli parcheggiati. Cosa devi fare?","answers":["Get out and look","Sound the horn and pull out","Move out quickly","Stop, then move slowly forward until you can see clearly"],"answers_it":["Scendere e guardare","Suonare e immetterti","Uscire rapidamente","Fermarti e avanzare lentamente finché la visuale è chiara"],"correct":[3],"explanation":"Creep forward slowly after stopping until you have a clear view.","explanation_it":"Dopo esserti fermato, avanza lentamente finché non hai una visuale chiara.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.11","category":"Motorcyclists and overtaking","status":"official_transport_malta","question":"You are at the front of a queue waiting to turn right into a side road. Why check your right mirror just before turning?","question_it":"Sei in testa a una coda e devi girare a destra in una strada laterale. Perché controllare lo specchio destro subito prima di svoltare?","answers":["To check emerging traffic","To check for overtaking vehicles","To check the side road","To look for pedestrians"],"answers_it":["Per controllare il traffico in uscita","Per controllare veicoli in sorpasso","Per controllare la strada laterale","Per cercare pedoni"],"correct":[1],"explanation":"A motorcycle or other vehicle may be overtaking on your right.","explanation_it":"Una moto o un altro veicolo potrebbe sorpassarti sulla destra.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.13","category":"Pedestrian crossings","status":"official_transport_malta","question":"At a pelican crossing, the red and amber lights are showing. What should you do?","question_it":"A un pelican crossing sono accese le luci rossa e gialla. Cosa devi fare?","answers":["Move off immediately","Always wait for green","Give way to pedestrians still on the crossing","Signal pedestrians to cross"],"answers_it":["Partire immediatamente","Aspettare sempre il verde","Dare precedenza ai pedoni ancora sull'attraversamento","Fare cenno ai pedoni di attraversare"],"correct":[2],"explanation":"Even when the signal is changing, pedestrians still on the crossing must be allowed to finish.","explanation_it":"Anche quando il segnale sta cambiando, devi permettere ai pedoni ancora sull'attraversamento di terminare.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.14","category":"Disabled pedestrians","status":"official_transport_malta","question":"A disabled person is crossing slowly at a pelican crossing and the light changes to green. What should you do? Select 2 answers.","question_it":"Una persona con disabilità attraversa lentamente a un pelican crossing e la luce diventa verde. Cosa devi fare? Seleziona 2 risposte.","answers":["Drive in front of the person","Edge forward slowly","Allow the person to cross","Sound the horn","Be patient","Drive behind the person"],"answers_it":["Passare davanti","Avanzare lentamente","Lasciarla attraversare","Suonare il clacson","Essere paziente","Passare dietro"],"correct":[2,4],"explanation":"Allow the person to complete the crossing and remain patient.","explanation_it":"Permetti alla persona di completare l'attraversamento e sii paziente.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.15","category":"Elderly pedestrians","status":"official_transport_malta","question":"The lights change to green but elderly pedestrians are halfway across a pelican crossing. What should you do?","question_it":"La luce diventa verde ma pedoni anziani sono ancora a metà del pelican crossing. Cosa devi fare?","answers":["Flash your headlights","Rev the engine","Wave them to hurry","Wait because they may take longer"],"answers_it":["Lampeggiare","Accelerare il motore","Fare cenno di sbrigarsi","Aspettare perché potrebbero impiegare più tempo"],"correct":[3],"explanation":"Wait patiently until they have completed the crossing.","explanation_it":"Aspetta con pazienza finché non hanno completato l'attraversamento.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.16","category":"Children","status":"official_transport_malta","question":"Near an ice-cream van, what is the danger you should be most aware of?","question_it":"Vicino a un furgone dei gelati, quale pericolo devi considerare soprattutto?","answers":["A parked car may move","The van driver may get out","The van may move","A child may run into the road"],"answers_it":["Un'auto parcheggiata potrebbe partire","Il conducente potrebbe scendere","Il furgone potrebbe partire","Un bambino potrebbe correre in strada"],"correct":[3],"explanation":"Children may run into the road unexpectedly near an ice-cream van.","explanation_it":"Vicino a un furgone dei gelati i bambini possono correre improvvisamente in strada.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.18","category":"Children","status":"official_transport_malta","question":"A ball bounces into the road from between parked cars. What should you do?","question_it":"Una palla rimbalza in strada tra auto parcheggiate. Cosa devi fare?","answers":["Stop and wave children across","Continue at the same speed and flash","Slow down and be prepared to stop for children","Continue and sound the horn"],"answers_it":["Fermarti e fare cenno ai bambini","Proseguire e lampeggiare","Rallentare e prepararti a fermarti per dei bambini","Proseguire e suonare"],"correct":[2],"explanation":"A child may run after the ball, so slow down and be ready to stop.","explanation_it":"Un bambino potrebbe correre dietro alla palla, quindi rallenta e preparati a fermarti.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.26","category":"Motorcyclists","status":"official_transport_malta","question":"You are following a motorcyclist on an uneven road. What should you do?","question_it":"Stai seguendo un motociclista su una strada sconnessa. Cosa devi fare?","answers":["Allow the same room as normal","Overtake immediately","Allow extra room in case the rider swerves to avoid potholes","Allow less room so the rider can see you"],"answers_it":["Lasciare lo stesso spazio del normale","Sorpassare immediatamente","Lasciare più spazio nel caso il motociclista devii per evitare buche","Lasciare meno spazio così il motociclista può vederti"],"correct":[2],"explanation":"Uneven surfaces may force a motorcyclist to change direction suddenly.","explanation_it":"Un fondo sconnesso può costringere il motociclista a cambiare direzione improvvisamente.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.33","category":"Vulnerable road users","status":"official_transport_malta","question":"Which TWO road users should you allow extra room when overtaking?","question_it":"A quali DUE utenti della strada devi lasciare più spazio durante il sorpasso?","answers":["Road-sweeping vehicles","Motorcycles","Tractors","Bicycles"],"answers_it":["Veicoli spazzatrici","Motocicli","Trattori","Biciclette"],"correct":[1,3],"explanation":"Motorcycles and bicycles are vulnerable to wind, road defects and sudden changes of direction.","explanation_it":"Motocicli e biciclette sono vulnerabili al vento, alle irregolarità della strada e ai cambi di direzione improvvisi.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.34","category":"Motorcyclists","status":"official_transport_malta","question":"Why should you allow extra room when overtaking a motorcyclist on a windy day?","question_it":"Perché devi lasciare più spazio quando sorpassi un motociclista in una giornata ventosa?","answers":["The rider may travel faster than normal","The rider may be blown across in front of you","The rider may stop suddenly","The rider may turn off suddenly"],"answers_it":["Il motociclista può viaggiare più velocemente del normale","Il motociclista può essere spinto dal vento davanti a te","Il motociclista può fermarsi improvvisamente","Il motociclista può svoltare improvvisamente"],"correct":[1],"explanation":"Strong crosswinds can push a motorcycle sideways.","explanation_it":"Le raffiche laterali possono spostare lateralmente il motociclo.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.35","category":"Wind","status":"official_transport_malta","question":"Which type of vehicle is most affected by strong winds?","question_it":"Quale tipo di veicolo è maggiormente influenzato dal vento forte?","answers":["Bowser","Motorcycle","Car","Tractor"],"answers_it":["Autocisterna","Motociclo","Automobile","Trattore"],"correct":[1],"explanation":"Motorcycles are light and exposed, so strong winds affect them most.","explanation_it":"I motocicli sono leggeri ed esposti, quindi risentono maggiormente del vento forte.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.36","category":"Motorcyclists and cyclists","status":"official_transport_malta","question":"Why should you particularly look for motorcyclists and cyclists at junctions?","question_it":"Perché devi prestare particolare attenzione a motociclisti e ciclisti agli incroci?","answers":["They might not see you turn","They may slow down to let you turn","They are harder to see","They always have priority"],"answers_it":["Potrebbero non vederti svoltare","Potrebbero rallentare per lasciarti svoltare","Sono più difficili da vedere","Hanno sempre la precedenza"],"correct":[2],"explanation":"Their smaller size makes them easy to miss.","explanation_it":"Le loro dimensioni ridotte li rendono facili da non notare.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.37","category":"Motorcyclists","status":"official_transport_malta","question":"You are waiting to emerge from a side road. Why should you watch carefully for motorcycles?","question_it":"Aspetti di uscire da una strada laterale. Perché devi controllare attentamente la presenza di motocicli?","answers":["Motorcycles always have priority","Police often use motorcycles","Motorcycles are small and hard to see","Motorcycles are always faster than cars"],"answers_it":["I motocicli hanno sempre la precedenza","La polizia usa spesso motocicli","I motocicli sono piccoli e difficili da vedere","I motocicli sono sempre più veloci delle auto"],"correct":[2],"explanation":"Motorcycles can be hidden by other traffic or roadside objects.","explanation_it":"I motocicli possono essere nascosti dal traffico o da oggetti ai lati della strada.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.43","category":"Motorcyclists","status":"official_transport_malta","question":"Why do motorcyclists often look over their right shoulder just before turning right?","question_it":"Perché i motociclisti guardano spesso sopra la spalla destra subito prima di svoltare a destra?","answers":["It helps them balance","Motorcycles have no mirrors","They need to listen for traffic","They need to check traffic in their blind area"],"answers_it":["Li aiuta a mantenere l'equilibrio","I motocicli non hanno specchi","Devono ascoltare il traffico","Devono controllare il traffico nell'angolo cieco"],"correct":[3],"explanation":"The shoulder check reveals traffic hidden in the blind spot.","explanation_it":"Il controllo sopra la spalla permette di vedere il traffico nascosto nell'angolo cieco.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.47","category":"Motorcyclists","status":"official_transport_malta","question":"Which THREE hazards may motorcyclists present in queues of traffic?","question_it":"Quali TRE pericoli possono presentare i motociclisti nelle code di traffico?","answers":["Passing very close to your car","Riding with dipped headlights","Riding in single file","Filtering between lanes","Cutting in just in front of you"],"answers_it":["Passare molto vicino alla tua auto","Guidare con gli anabbaglianti","Procedere in fila indiana","Filtrare tra le corsie","Rientrare subito davanti a te"],"correct":[0,3,4],"explanation":"Motorcyclists may pass close, filter between lanes and cut in ahead.","explanation_it":"I motociclisti possono passare molto vicino, filtrare tra le corsie e rientrare subito davanti.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.49","category":"Motorcyclists","status":"official_transport_malta","question":"You are driving in slow-moving traffic. Just before changing lane, what should you do?","question_it":"Guidi in traffico lento. Subito prima di cambiare corsia, cosa devi fare?","answers":["Change down to first gear","Give a slowing-down arm signal","Sound the horn","Look for motorcyclists filtering through traffic"],"answers_it":["Scalare in prima","Fare un segnale con il braccio","Suonare il clacson","Controllare la presenza di motociclisti che filtrano nel traffico"],"correct":[3],"explanation":"Motorcyclists may be filtering between lanes and can be hidden in blind spots.","explanation_it":"I motociclisti possono filtrare tra le corsie ed essere nascosti negli angoli ciechi.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.59","category":"Accidents","status":"official_transport_malta","question":"You have a collision while your car is moving. What is the first important thing you must do?","question_it":"Hai una collisione mentre l'auto è in movimento. Qual è la prima cosa importante da fare?","answers":["Call your insurance company","Call emergency services","Stop at the scene","Stop only if someone is injured"],"answers_it":["Chiamare l'assicurazione","Chiamare i soccorsi","Fermarti sul luogo dell'incidente","Fermarti solo se qualcuno è ferito"],"correct":[2],"explanation":"You must stop at the scene of a collision.","explanation_it":"Devi fermarti sul luogo della collisione.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.63","category":"Pedestrian safety","status":"official_transport_malta","question":"A car hits a pedestrian at 60 kph. What is the likely result?","question_it":"Un'auto investe un pedone a 60 km/h. Qual è il risultato probabile?","answers":["The pedestrian will probably survive","The pedestrian will certainly survive","The pedestrian will probably be killed","The pedestrian will certainly be killed"],"answers_it":["Il pedone probabilmente sopravviverà","Il pedone sopravviverà certamente","Il pedone probabilmente morirà","Il pedone morirà certamente"],"correct":[2],"explanation":"The probability of fatal injury is very high at 60 kph.","explanation_it":"A 60 km/h la probabilità di lesioni mortali è molto alta.","source":"Transport Malta Cars Version 4"},{"id":"CARS6.64","category":"Night driving","status":"official_transport_malta","question":"You are dazzled at night by the lights of the vehicle behind. What should you do?","question_it":"Di notte vieni abbagliato dalle luci del veicolo dietro. Cosa devi fare?","answers":["Set the mirror to anti-dazzle","Switch rear lights on and off","Brake sharply","Adjust the mirror to dazzle the other driver"],"answers_it":["Impostare lo specchio in modalità antiabbagliamento","Accendere e spegnere le luci posteriori","Frenare bruscamente","Regolare lo specchio per abbagliare l'altro conducente"],"correct":[0],"explanation":"Use the anti-dazzle setting on the interior mirror.","explanation_it":"Usa la posizione antiabbagliamento dello specchio interno.","source":"Transport Malta Cars Version 4"},{"id":"CARS7.1","category":"Motorcyclists","status":"official_transport_malta","question":"The road is wet and slippery. Why might a motorcyclist steer around drain covers on a bend?","question_it":"La strada è bagnata e scivolosa. Perché un motociclista potrebbe evitare i tombini in curva?","answers":["To avoid splashing pedestrians","To use them as bend markers","To prevent punctures","To prevent the motorcycle sliding on the metal covers"],"answers_it":["Per evitare di bagnare i pedoni","Per usarli come riferimento in curva","Per evitare forature","Per evitare che il motociclo scivoli sul metallo"],"correct":[3],"explanation":"Wet metal covers can be very slippery for motorcycles.","explanation_it":"I tombini metallici bagnati possono essere molto scivolosi per i motocicli.","source":"Transport Malta Cars Version 4"},{"id":"CARS11.70","category":"Junctions","status":"official_transport_malta","question":"You are waiting at a T-junction. A vehicle is coming from the right with its left indicator flashing. What should you do?","question_it":"Aspetti a un incrocio a T. Un veicolo arriva da destra con l'indicatore sinistro acceso. Cosa devi fare?","answers":["Move out slowly","Wait until the vehicle starts to turn","Pull out before it reaches the junction","Move out and accelerate hard"],"answers_it":["Uscire lentamente","Aspettare finché il veicolo inizia effettivamente a svoltare","Immetterti prima che raggiunga l'incrocio","Uscire accelerando forte"],"correct":[1],"explanation":"Do not rely only on the indicator; wait until the vehicle begins to turn.","explanation_it":"Non affidarti soltanto all'indicatore; aspetta che il veicolo inizi davvero a svoltare.","source":"Transport Malta Cars Version 4"},{"id":"CARS11.73","category":"Speed limits","status":"official_transport_malta","question":"What is the maximum speed limit in a built-up area unless indicated otherwise?","question_it":"Qual è il limite massimo di velocità in un centro abitato, salvo diversa indicazione?","answers":["60 kph","40 kph","50 kph","30 kph"],"answers_it":["60 km/h","40 km/h","50 km/h","30 km/h"],"correct":[2],"explanation":"The default built-up-area limit is 50 kph unless signs indicate otherwise.","explanation_it":"Il limite predefinito nei centri abitati è 50 km/h salvo diversa segnalazione.","source":"Transport Malta Cars Version 4"},{"id":"CARS12.3","category":"Insurance","status":"official_transport_malta","question":"Before driving someone else's vehicle, what must you make sure of?","question_it":"Prima di guidare il veicolo di un'altra persona, di cosa devi assicurarti?","answers":["The insurance papers are in the vehicle","Your own vehicle is insured","The vehicle is insured for your use","The owner has third-party cover"],"answers_it":["Che i documenti assicurativi siano nel veicolo","Che il tuo veicolo sia assicurato","Che il veicolo sia assicurato anche per il tuo utilizzo","Che il proprietario abbia copertura verso terzi"],"correct":[2],"explanation":"You must be specifically covered to drive that vehicle.","explanation_it":"Devi essere specificamente coperto dall'assicurazione per guidare quel veicolo.","source":"Transport Malta Cars Version 4"},{"id":"CARS12.4","category":"Insurance","status":"official_transport_malta","question":"What is the legal minimum insurance cover required to drive on public roads?","question_it":"Qual è la copertura assicurativa minima legale necessaria per guidare su strada pubblica?","answers":["Personal injury cover","Fully comprehensive","Third party, fire and theft","Third party only"],"answers_it":["Copertura infortuni personale","Kasko completa","Responsabilità civile, incendio e furto","Solo responsabilità civile verso terzi"],"correct":[3],"explanation":"Third-party insurance is the legal minimum.","explanation_it":"La responsabilità civile verso terzi è la copertura minima legale.","source":"Transport Malta Cars Version 4"},{"id":"CARS12.7","category":"Documents","status":"official_transport_malta","question":"Which THREE items do you need before you can drive legally?","question_it":"Quali TRE elementi servono prima di poter guidare legalmente?","answers":["Proper insurance cover","A vehicle handbook","Breakdown cover","A valid road tax disc displayed","A valid signed driving licence","Proof of identity"],"answers_it":["Copertura assicurativa adeguata","Manuale del veicolo","Assistenza stradale","Bollo valido esposto","Patente valida e firmata","Documento d'identità"],"correct":[0,3,4],"explanation":"You need valid insurance, valid road tax and a valid driving licence.","explanation_it":"Servono assicurazione valida, bollo valido e patente valida.","source":"Transport Malta Cars Version 4"},{"id":"CARS11.30","category":"Road and traffic signs","status":"official_transport_malta","question":"What are triangular signs for?","question_it":"A cosa servono i segnali triangolari?","answers":["To give warnings","To give directions","To give orders","To give information"],"answers_it":["A segnalare pericoli","A dare indicazioni","A dare ordini","A fornire informazioni"],"correct":[0],"explanation":"Triangular road signs are generally warning signs.","explanation_it":"I segnali stradali triangolari sono generalmente segnali di pericolo.","source":"Transport Malta Cars Version 4"},{"id":"CARS11.34","category":"Road and traffic signs","status":"official_transport_malta","question":"Which FOUR of these would be indicated by a triangular road sign?","question_it":"Quali QUATTRO di questi elementi sarebbero indicati da un segnale triangolare?","answers":["Ahead only","Children crossing","T-junction","Road narrows","Tunnel ahead","Minimum speed"],"answers_it":["Solo dritto","Attraversamento bambini","Incrocio a T","Strada che si restringe","Galleria davanti","Velocità minima"],"correct":[1,2,3,4],"explanation":"Children crossing, T-junction, road narrows and tunnel ahead are warning situations shown by triangular signs.","explanation_it":"Attraversamento bambini, incrocio a T, restringimento della strada e galleria davanti sono situazioni di pericolo indicate da segnali triangolari.","source":"Transport Malta Cars Version 4"},{"id":"CARS11.55","category":"Traffic lights","status":"official_transport_malta","question":"You are approaching a red traffic light. The signal will change from red to:","question_it":"Ti avvicini a un semaforo rosso. Il segnale cambierà da rosso a:","answers":["Red and amber, then green","Green and amber, then green","Amber, then green","Green, then amber"],"answers_it":["Rosso e giallo, poi verde","Verde e giallo, poi verde","Giallo, poi verde","Verde, poi giallo"],"correct":[0],"explanation":"The normal sequence is red, then red and amber together, then green.","explanation_it":"La sequenza normale è rosso, poi rosso e giallo insieme, quindi verde.","source":"Transport Malta Cars Version 4"},{"id":"CARS11.56","category":"Traffic lights","status":"official_transport_malta","question":"A red traffic light means:","question_it":"Un semaforo rosso significa:","answers":["Proceed with caution","Stop if you are able to brake safely","You must stop and wait behind the stop line","You may turn left if it is safe"],"answers_it":["Procedere con cautela","Fermarti se riesci a frenare in sicurezza","Devi fermarti e attendere dietro la linea di arresto","Puoi girare a sinistra se è sicuro"],"correct":[2],"explanation":"A red signal requires you to stop and wait behind the stop line.","explanation_it":"Il rosso impone di fermarti e attendere dietro la linea di arresto.","source":"Transport Malta Cars Version 4"},{"id":"CARS11.57","category":"Traffic lights","status":"official_transport_malta","question":"At traffic lights, amber on its own means:","question_it":"Al semaforo, la luce gialla da sola significa:","answers":["Go if no pedestrians are crossing","Go if the way is clear","Prepare to go","Prepare to stop at the stop line"],"answers_it":["Passare se non ci sono pedoni","Passare se la strada è libera","Prepararti a partire","Prepararti a fermarti alla linea di arresto"],"correct":[3],"explanation":"Amber means stop at the stop line unless it would be unsafe to do so because you are too close.","explanation_it":"Il giallo significa prepararti a fermarti alla linea di arresto, salvo che tu sia troppo vicino per farlo in sicurezza.","source":"Transport Malta Cars Version 4"},{"id":"CARS11.58","category":"Traffic lights","status":"official_transport_malta","question":"A red traffic light means:","question_it":"Un semaforo rosso significa:","answers":["You must stop behind the white stop line","You must slow down and prepare to stop if traffic has started to cross","You may turn left if it is safe","You may drive straight on if there is no other traffic"],"answers_it":["Devi fermarti dietro la linea bianca di arresto","Devi soltanto rallentare se il traffico ha iniziato ad attraversare","Puoi girare a sinistra se è sicuro","Puoi proseguire dritto se non c'è traffico"],"correct":[0],"explanation":"Red means you must stop behind the white stop line.","explanation_it":"Il rosso significa che devi fermarti dietro la linea bianca di arresto.","source":"Transport Malta Cars Version 4"},{"id":"CARS4.1","category":"ABS and emergency braking","status":"official_transport_malta","question":"If your car is fitted with anti-lock brakes and you need to stop in an emergency, what should you do?","question_it":"Se l'auto è dotata di ABS e devi fermarti in emergenza, cosa devi fare?","answers":["Apply the handbrake to reduce the stopping distance","Press the brake pedal rapidly and firmly until you have stopped","Keep pushing and releasing the foot brake quickly","Brake normally and avoid turning the steering wheel"],"answers_it":["Usare il freno a mano per ridurre la distanza","Premere rapidamente e con forza il pedale del freno fino all'arresto","Premere e rilasciare rapidamente il freno","Frenare normalmente senza girare lo sterzo"],"correct":[1],"explanation":"With ABS, press the brake firmly and keep it applied while steering if necessary.","explanation_it":"Con l'ABS premi con forza il freno e mantienilo premuto, sterzando se necessario.","source":"Transport Malta Cars Version 4"},{"id":"CARS4.2","category":"ABS and emergency braking","status":"official_transport_malta","question":"Anti-lock brakes reduce the chance of skidding particularly when:","question_it":"L'ABS riduce soprattutto il rischio di slittamento quando:","answers":["Driving on good road surfaces","Braking during normal driving","Braking in an emergency","Driving down steep hills"],"answers_it":["Guidi su fondo buono","Freni normalmente","Freni in emergenza","Scendi da una forte pendenza"],"correct":[2],"explanation":"ABS is especially valuable during emergency braking.","explanation_it":"L'ABS è particolarmente utile durante una frenata d'emergenza.","source":"Transport Malta Cars Version 4"},{"id":"CARS4.3","category":"ABS and steering","status":"official_transport_malta","question":"Vehicles fitted with anti-lock brakes:","question_it":"I veicoli dotati di ABS:","answers":["Do not have a handbrake","Can be steered while braking","Accelerate much faster","Cannot skid"],"answers_it":["Non hanno il freno a mano","Possono essere sterzati durante la frenata","Accelerano molto più rapidamente","Non possono slittare"],"correct":[1],"explanation":"ABS helps preserve steering control under heavy braking.","explanation_it":"L'ABS aiuta a mantenere il controllo dello sterzo durante una frenata intensa.","source":"Transport Malta Cars Version 4"},{"id":"CARS4.4","category":"ABS and road surface","status":"official_transport_malta","question":"Anti-lock brakes may not work as effectively as expected if the road surface is: Select 2 answers.","question_it":"L'ABS può funzionare meno efficacemente del previsto se il fondo stradale è: Seleziona 2 risposte.","answers":["Firm","Loose","Good","Dry","Wet"],"answers_it":["Compatto","Sconnesso o con materiale sciolto","Buono","Asciutto","Bagnato"],"correct":[1,4],"explanation":"Loose or wet surfaces can reduce tyre grip and ABS effectiveness.","explanation_it":"Fondi sconnessi o bagnati possono ridurre l'aderenza e l'efficacia dell'ABS.","source":"Transport Malta Cars Version 4"},{"id":"CARS4.12","category":"Skidding","status":"official_transport_malta","question":"What is the most common reason a car skids?","question_it":"Qual è la causa più comune dello slittamento di un'auto?","answers":["Pedestrians","Driver error","Other vehicles","Worn tyres"],"answers_it":["Pedoni","Errore del conducente","Altri veicoli","Pneumatici usurati"],"correct":[1],"explanation":"Most skids are caused by inappropriate speed, steering or braking by the driver.","explanation_it":"La maggior parte degli slittamenti è causata da velocità, sterzata o frenata inadeguate del conducente.","source":"Transport Malta Cars Version 4"},{"id":"CARS4.13","category":"Braking dynamics","status":"official_transport_malta","question":"When braking hard in a straight line, most of the vehicle's weight shifts onto the:","question_it":"Durante una frenata forte in linea retta, la maggior parte del peso del veicolo si sposta sulle:","answers":["Front wheels","Right wheels","Left wheels","Rear wheels"],"answers_it":["Ruote anteriori","Ruote destre","Ruote sinistre","Ruote posteriori"],"correct":[0],"explanation":"Hard braking transfers weight forward onto the front wheels.","explanation_it":"Una frenata forte trasferisce il peso in avanti sulle ruote anteriori.","source":"Transport Malta Cars Version 4"},{"id":"CARS4.15","category":"Floods and brakes","status":"official_transport_malta","question":"You have driven your car through a flood. What is the first thing you should do?","question_it":"Hai attraversato una zona allagata con l'auto. Qual è la prima cosa da fare?","answers":["Switch on the windscreen wipers","Stop and dry the brakes","Stop and check the tyres","Test your brakes"],"answers_it":["Accendere i tergicristalli","Fermarti e asciugare i freni","Fermarti e controllare gli pneumatici","Provare i freni"],"correct":[3],"explanation":"Test the brakes gently after passing through water because they may be less effective.","explanation_it":"Dopo aver attraversato l'acqua prova delicatamente i freni, perché potrebbero essere meno efficaci.","source":"Transport Malta Cars Version 4"},{"id":"CARS8.36","category":"Narrow roads","status":"official_transport_malta","question":"You see a vehicle coming towards you on a narrow single-track road. What should you do?","question_it":"Vedi un veicolo arrivare verso di te su una strada stretta a corsia unica. Cosa devi fare?","answers":["Switch on hazard warning lights","Make an emergency stop","Stop at a passing place","Reverse back to the main road"],"answers_it":["Accendere le quattro frecce","Fare una frenata d'emergenza","Fermarti in una piazzola di scambio","Fare retromarcia fino alla strada principale"],"correct":[2],"explanation":"Use a passing place to allow the vehicles to pass safely.","explanation_it":"Usa una piazzola di scambio per permettere ai veicoli di passare in sicurezza.","source":"Transport Malta Cars Version 4"},{"id":"CARS9.1","category":"Dual carriageways","status":"official_transport_malta","question":"As soon as you join a dual carriageway, where should you normally position your vehicle?","question_it":"Appena entri in una strada a doppia carreggiata, dove devi normalmente posizionarti?","answers":["In the centre lane","Readjust your mirrors","Try to overtake","In the left lane"],"answers_it":["Nella corsia centrale","Regolare nuovamente gli specchi","Provare a sorpassare","Nella corsia sinistra"],"correct":[3],"explanation":"Keep left unless overtaking.","explanation_it":"Mantieni la sinistra salvo durante il sorpasso.","source":"Transport Malta Cars Version 4"},{"id":"CARS9.2","category":"Dual carriageways","status":"official_transport_malta","question":"When joining a dual carriageway, what must you always do?","question_it":"Quando ti immetti su una strada a doppia carreggiata, cosa devi sempre fare?","answers":["Stop before joining","Stop at the end of the acceleration lane","Use the hard shoulder","Give way to traffic already on the carriageway"],"answers_it":["Fermarti prima di entrare","Fermarti alla fine della corsia di accelerazione","Usare la corsia di emergenza","Dare precedenza al traffico già sulla carreggiata"],"correct":[3],"explanation":"Traffic already on the carriageway has priority.","explanation_it":"Il traffico già presente sulla carreggiata ha la precedenza.","source":"Transport Malta Cars Version 4"},{"id":"CARS9.3","category":"Dual carriageways","status":"official_transport_malta","question":"What is a fundamental rule when driving on a dual carriageway?","question_it":"Qual è una regola fondamentale quando guidi su una strada a doppia carreggiata?","answers":["Keep above 50 kph","Keep in the left lane unless overtaking","Overtake on whichever side is clear","Use the lane with least traffic"],"answers_it":["Restare sopra i 50 km/h","Tenere la corsia sinistra salvo sorpasso","Sorpassare dal lato libero","Usare la corsia meno trafficata"],"correct":[1],"explanation":"Normally keep left and use other lanes only when overtaking.","explanation_it":"Normalmente mantieni la sinistra e usa le altre corsie solo per sorpassare.","source":"Transport Malta Cars Version 4"},{"id":"CARS9.4","category":"Hazard warning lights","status":"official_transport_malta","question":"A vehicle ahead briefly shows its hazard warning lights on a dual carriageway. What does this mean?","question_it":"Un veicolo davanti accende brevemente le quattro frecce su una strada a doppia carreggiata. Cosa significa?","answers":["There is a police speed check","The vehicle will change lane","Traffic ahead is slowing or stopping suddenly","The driver wants you to overtake"],"answers_it":["C'è un controllo della velocità","Il veicolo cambierà corsia","Il traffico davanti sta rallentando o fermandosi improvvisamente","Il conducente vuole che tu sorpassi"],"correct":[2],"explanation":"Hazard lights may warn following traffic of sudden slowing or stopping.","explanation_it":"Le quattro frecce possono avvertire chi segue di un rallentamento o arresto improvviso.","source":"Transport Malta Cars Version 4"},{"id":"CARS9.5","category":"Hazard warning lights","status":"official_transport_malta","question":"You have to slow down quickly on a dual carriageway because of a hazard. What should you do?","question_it":"Devi rallentare rapidamente su una strada a doppia carreggiata a causa di un pericolo. Cosa devi fare?","answers":["Switch on your hazard warning lights","Flash your headlights","Sound your horn","Switch on full headlights"],"answers_it":["Accendere le quattro frecce","Lampeggiare con i fari","Suonare il clacson","Accendere gli abbaglianti"],"correct":[0],"explanation":"Use hazard warning lights to alert traffic behind of the sudden hazard.","explanation_it":"Usa le quattro frecce per avvertire il traffico dietro del pericolo improvviso.","source":"Transport Malta Cars Version 4"},{"id":"CARS9.6","category":"Flashing beacons","status":"official_transport_malta","question":"Which vehicles are normally fitted with amber flashing beacons? Select 2 answers.","question_it":"Quali veicoli sono normalmente dotati di lampeggianti gialli? Seleziona 2 risposte.","answers":["Coastguard","Maintenance vehicles","Blood transfusion team","Breakdown recovery vehicles","Doctor's car"],"answers_it":["Guardia costiera","Veicoli di manutenzione","Servizio trasfusioni","Veicoli di soccorso stradale","Auto del medico"],"correct":[1,3],"explanation":"Maintenance and breakdown-recovery vehicles commonly use amber beacons.","explanation_it":"I veicoli di manutenzione e soccorso stradale usano normalmente lampeggianti gialli.","source":"Transport Malta Cars Version 4"},{"id":"LPTV2026.021","category":"LPTV Law 2026","status":"official_transport_malta","question":"Which operator licence category applies to operators with five or more authorised vehicles?","question_it":"Quale categoria di licenza operatore si applica agli operatori con cinque o più veicoli autorizzati?","answers":["LPTV1","LPTV2","SOV only","Taxi Driver Permit"],"answers_it":["LPTV1","LPTV2","Solo SOV","Permesso conducente taxi"],"correct":[1],"explanation":"LPTV2 applies to operators with five or more authorised vehicles.","explanation_it":"La licenza LPTV2 si applica agli operatori con cinque o più veicoli autorizzati.","source":"Transport Malta - Changes Effective from 29 July 2026"},{"id":"LPTV2026.022","category":"LPTV Law 2026","status":"official_transport_malta","question":"May LPTV1 and LPTV2 vehicles provide independently arranged pre-booked services?","question_it":"I veicoli LPTV1 e LPTV2 possono fornire servizi prenotati direttamente e organizzati in modo indipendente?","answers":["Yes","No","Only at airports","Only at weekends"],"answers_it":["Sì","No","Solo negli aeroporti","Solo nei fine settimana"],"correct":[0],"explanation":"LPTV1 and LPTV2 vehicles may work through platforms and may also provide independently arranged pre-booked services.","explanation_it":"I veicoli LPTV1 e LPTV2 possono lavorare tramite piattaforme e anche fornire servizi prenotati direttamente.","source":"Transport Malta - Changes Effective from 29 July 2026"},{"id":"LPTV2026.023","category":"Parking","status":"official_transport_malta","question":"For how long may an SOV vehicle remain parked on the road when not in use?","question_it":"Per quanto tempo può restare parcheggiato su strada un veicolo SOV quando non è in uso?","answers":["One hour","Two hours","Three hours","Four hours"],"answers_it":["Un'ora","Due ore","Tre ore","Quattro ore"],"correct":[2],"explanation":"An SOV vehicle may remain parked on the road for a maximum of three hours.","explanation_it":"Un veicolo SOV può rimanere parcheggiato su strada per un massimo di tre ore.","source":"Transport Malta - Changes Effective from 29 July 2026"},{"id":"LPTV2026.024","category":"Parking","status":"official_transport_malta","question":"Does the three-hour SOV parking limit apply only during daytime?","question_it":"Il limite di tre ore per la sosta SOV si applica solo durante il giorno?","answers":["Yes","No, it applies throughout day and night","Only between 05:01 and 16:59","Only after 17:00"],"answers_it":["Sì","No, si applica durante tutto il giorno e la notte","Solo tra le 05:01 e le 16:59","Solo dopo le 17:00"],"correct":[1],"explanation":"The three-hour SOV limit applies throughout the day and night.","explanation_it":"Il limite di tre ore per i veicoli SOV si applica sia di giorno sia di notte.","source":"Transport Malta - Changes Effective from 29 July 2026"},{"id":"LPTV2026.025","category":"Garaging","status":"official_transport_malta","question":"When an authorised vehicle is not in use, where should it normally be parked?","question_it":"Quando un veicolo autorizzato non è in uso, dove dovrebbe normalmente essere parcheggiato?","answers":["Anywhere on a public road","In approved garaging or otherwise off-street as required","Only at a taxi stand","Only outside the operator's home"],"answers_it":["Ovunque su strada pubblica","In un garage approvato o comunque fuori strada secondo i requisiti","Solo presso un taxi stand","Solo fuori dall'abitazione dell'operatore"],"correct":[1],"explanation":"Approved garaging or compliant off-street parking is the general rule; on-street parking is an exception.","explanation_it":"Il garage approvato o la sosta fuori strada conforme è la regola generale; la sosta su strada è un'eccezione.","source":"Transport Malta - Changes Effective from 29 July 2026"},{"id":"LPTV2026.026","category":"Garaging","status":"official_transport_malta","question":"What must operators ensure regarding approved garaging capacity?","question_it":"Cosa devono garantire gli operatori riguardo alla capacità del garage approvato?","answers":["It is sufficient for the authorised vehicles","It is shared with any other operator","It is used only at night","It is located next to a taxi stand"],"answers_it":["Che sia sufficiente per i veicoli autorizzati","Che sia condivisa con qualsiasi altro operatore","Che sia usata solo di notte","Che sia accanto a un taxi stand"],"correct":[0],"explanation":"Operators must ensure sufficient approved garaging capacity for their authorised vehicles.","explanation_it":"Gli operatori devono garantire una capacità di garaging approvata sufficiente per i veicoli autorizzati.","source":"Transport Malta - Changes Effective from 29 July 2026"},{"id":"LPTV2026.027","category":"Special Occasion Vehicles","status":"official_transport_malta","question":"Must SOV services be pre-booked?","question_it":"I servizi SOV devono essere prenotati in anticipo?","answers":["Yes","No","Only for weddings","Only for airport transfers"],"answers_it":["Sì","No","Solo per matrimoni","Solo per trasferimenti aeroportuali"],"correct":[0],"explanation":"SOV services must be pre-booked.","explanation_it":"I servizi SOV devono essere prenotati in anticipo.","source":"Transport Malta - Changes Effective from 29 July 2026"},{"id":"LPTV2026.028","category":"Special Occasion Vehicles","status":"official_transport_malta","question":"Can an SOV vehicle also operate at the same time as a Y-plate vehicle through a booking platform?","question_it":"Un veicolo SOV può operare contemporaneamente anche come veicolo con targa Y tramite una piattaforma?","answers":["Yes","No","Only after midnight","Only with passenger consent"],"answers_it":["Sì","No","Solo dopo mezzanotte","Solo con il consenso del passeggero"],"correct":[1],"explanation":"An SOV vehicle cannot simultaneously operate as a Y-plate platform vehicle.","explanation_it":"Un veicolo SOV non può operare contemporaneamente come veicolo con targa Y tramite piattaforma.","source":"Transport Malta - Changes Effective from 29 July 2026"},{"id":"LPTV2026.029","category":"Intermediary booking platforms","status":"official_transport_malta","question":"Before a vehicle operates through an intermediary booking platform, what must be valid? Select 3 answers.","question_it":"Prima che un veicolo operi tramite una piattaforma intermediaria, cosa deve essere valido? Seleziona 3 risposte.","answers":["The Operator Licence","The vehicle documentation","The driver's applicable documentation","A handwritten receipt book","A private parking permit"],"answers_it":["La licenza dell'operatore","La documentazione del veicolo","La documentazione applicabile del conducente","Un blocchetto di ricevute scritto a mano","Un permesso di parcheggio privato"],"correct":[0,1,2],"explanation":"The Operator Licence, vehicle documentation and driver documentation must remain valid.","explanation_it":"La licenza dell'operatore, la documentazione del veicolo e quella del conducente devono essere valide.","source":"Transport Malta - Changes Effective from 29 July 2026"},{"id":"LPTV2026.030","category":"Intermediary booking platforms","status":"official_transport_malta","question":"What must a driver operating through a platform complete when requested?","question_it":"Cosa deve completare un conducente che opera tramite piattaforma quando gli viene richiesto?","answers":["Facial-recognition verification","A practical driving test every time","A VRT test","A fuel receipt"],"answers_it":["La verifica tramite riconoscimento facciale","Un esame pratico ogni volta","Un controllo VRT","Una ricevuta del carburante"],"correct":[0],"explanation":"Drivers must complete the required facial-recognition verification when requested by the platform.","explanation_it":"I conducenti devono completare la verifica tramite riconoscimento facciale quando richiesta dalla piattaforma.","source":"Transport Malta - Changes Effective from 29 July 2026"},{"id":"LPTV2026.031","category":"Operator responsibilities","status":"official_transport_malta","question":"Who must ensure that a platform vehicle is driven by the appropriately registered and authorised driver?","question_it":"Chi deve assicurarsi che un veicolo di piattaforma sia guidato dal conducente correttamente registrato e autorizzato?","answers":["The passenger","The operator","The fuel station","The vehicle manufacturer"],"answers_it":["Il passeggero","L'operatore","Il distributore di carburante","Il costruttore del veicolo"],"correct":[1],"explanation":"The operator must ensure that the authorised vehicle is driven by the properly registered and authorised driver.","explanation_it":"L'operatore deve garantire che il veicolo autorizzato sia guidato dal conducente correttamente registrato e autorizzato.","source":"Transport Malta - Changes Effective from 29 July 2026"},{"id":"LPTV2026.032","category":"Driver requirements","status":"official_transport_malta","question":"What must an LPTV driver continue to hold while operating a light passenger transport vehicle? Select 2 answers.","question_it":"Cosa deve continuare a possedere un conducente LPTV mentre guida un veicolo per trasporto leggero di passeggeri? Seleziona 2 risposte.","answers":["A valid driving licence","The appropriate Transport Malta Driver Permit Tag","A taxi meter certificate","A private parking card"],"answers_it":["Una patente di guida valida","Il relativo Driver Permit Tag di Transport Malta","Un certificato del tassametro","Una tessera di parcheggio privato"],"correct":[0,1],"explanation":"The driver must hold both a valid driving licence and the applicable Driver Permit Tag.","explanation_it":"Il conducente deve possedere sia una patente valida sia il Driver Permit Tag applicabile.","source":"Transport Malta - Changes Effective from 29 July 2026"},{"id":"LPTV2026.033","category":"Driver requirements","status":"official_transport_malta","question":"Who is responsible for ensuring that drivers are legally employed or commissioned and registered as required?","question_it":"Chi è responsabile di garantire che i conducenti siano legalmente assunti o incaricati e registrati come richiesto?","answers":["The passenger","The operator","The insurance broker","The vehicle dealer"],"answers_it":["Il passeggero","L'operatore","Il broker assicurativo","Il concessionario"],"correct":[1],"explanation":"The operator is responsible for ensuring proper employment or commissioning and registration.","explanation_it":"L'operatore è responsabile della corretta assunzione o collaborazione e della registrazione.","source":"Transport Malta - Changes Effective from 29 July 2026"},{"id":"LPTV2026.034","category":"Driver requirements","status":"official_transport_malta","question":"Which rules apply to complete Driver Permit Tag applications submitted on or before 28 July 2026?","question_it":"Quali regole si applicano alle domande complete per il Driver Permit Tag presentate entro il 28 luglio 2026?","answers":["The eligibility rules in force before the new regulations","Only the new 29 July 2026 rules","No eligibility rules","Taxi rules only"],"answers_it":["I requisiti in vigore prima delle nuove norme","Solo le nuove regole del 29 luglio 2026","Nessun requisito","Solo le regole taxi"],"correct":[0],"explanation":"Complete applications submitted by 28 July 2026 continue under the previous eligibility requirements.","explanation_it":"Le domande complete presentate entro il 28 luglio 2026 continuano a seguire i requisiti precedenti.","source":"Transport Malta - Changes Effective from 29 July 2026"},{"id":"LPTV2026.035","category":"Driving and rest periods","status":"official_transport_malta","question":"Do the working and rest requirements apply only to platform work?","question_it":"I requisiti di lavoro e riposo si applicano solo al lavoro tramite piattaforma?","answers":["Yes","No, they also apply to independently arranged services","Only to SOV services","Only to airport transfers"],"answers_it":["Sì","No, si applicano anche ai servizi organizzati indipendentemente","Solo ai servizi SOV","Solo ai trasferimenti aeroportuali"],"correct":[1],"explanation":"The limits apply whether services are provided through a platform or independently arranged.","explanation_it":"I limiti si applicano sia ai servizi tramite piattaforma sia a quelli organizzati indipendentemente.","source":"Transport Malta - Changes Effective from 29 July 2026"},{"id":"LPTV2026.036","category":"Driving and rest periods","status":"official_transport_malta","question":"What must operators maintain regarding drivers' working and rest periods?","question_it":"Cosa devono conservare gli operatori riguardo ai periodi di lavoro e riposo dei conducenti?","answers":["The required records","Only fuel receipts","Only customer reviews","No records"],"answers_it":["I registri richiesti","Solo le ricevute del carburante","Solo le recensioni dei clienti","Nessun registro"],"correct":[0],"explanation":"Required records of working and rest periods must be maintained and made available when requested.","explanation_it":"I registri richiesti sui periodi di lavoro e riposo devono essere conservati e resi disponibili su richiesta.","source":"Transport Malta - Changes Effective from 29 July 2026"},{"id":"LPTV2026.037","category":"Operator responsibilities","status":"official_transport_malta","question":"When a driver is added to or removed from an operation, what must the operator do?","question_it":"Quando un conducente viene aggiunto o rimosso da un'attività, cosa deve fare l'operatore?","answers":["Update the relevant Transport Malta records","Wait until the annual renewal","Inform passengers only","Change the vehicle colour"],"answers_it":["Aggiornare i relativi registri di Transport Malta","Attendere il rinnovo annuale","Informare solo i passeggeri","Cambiare il colore del veicolo"],"correct":[0],"explanation":"The relevant records with Transport Malta must be updated.","explanation_it":"I relativi registri presso Transport Malta devono essere aggiornati.","source":"Transport Malta - Changes Effective from 29 July 2026"},{"id":"LPTV2026.038","category":"Operator responsibilities","status":"official_transport_malta","question":"Which form is used to register applicable driver details with Transport Malta?","question_it":"Quale modulo viene usato per registrare i dati applicabili del conducente presso Transport Malta?","answers":["LPTS010","DRV001","VRT500","SOV100"],"answers_it":["LPTS010","DRV001","VRT500","SOV100"],"correct":[0],"explanation":"Form LPTS010 is used to register the applicable driver details.","explanation_it":"Il modulo LPTS010 viene usato per registrare i dati applicabili del conducente.","source":"Transport Malta - Changes Effective from 29 July 2026"},{"id":"LPTV2026.039","category":"Operator responsibilities","status":"official_transport_malta","question":"Which information must operators keep accurate and up to date? Select 3 answers.","question_it":"Quali informazioni devono essere mantenute accurate e aggiornate dagli operatori? Seleziona 3 risposte.","answers":["Vehicle information","Driver information","Garaging information","Passenger social-media accounts","Fuel-brand preferences"],"answers_it":["Informazioni sui veicoli","Informazioni sui conducenti","Informazioni sul garaging","Account social dei passeggeri","Preferenze sulla marca di carburante"],"correct":[0,1,2],"explanation":"Operator, vehicle, driver, operating-centre and garaging information must remain accurate and current.","explanation_it":"Le informazioni su operatore, veicoli, conducenti, centro operativo e garaging devono essere accurate e aggiornate.","source":"Transport Malta - Changes Effective from 29 July 2026"},{"id":"LPTV2026.040","category":"Enforcement","status":"official_transport_malta","question":"When requested for monitoring or enforcement, what must operators provide?","question_it":"Quando richiesto per monitoraggio o controllo, cosa devono fornire gli operatori?","answers":["Required records and documentation","Only customer names","Only vehicle photographs","Nothing without a court case"],"answers_it":["I registri e la documentazione richiesti","Solo i nomi dei clienti","Solo fotografie del veicolo","Nulla senza una causa giudiziaria"],"correct":[0],"explanation":"Required records and documentation must be made available to Transport Malta or authorised enforcement officers.","explanation_it":"I registri e la documentazione richiesti devono essere messi a disposizione di Transport Malta o degli agenti autorizzati.","source":"Transport Malta - Changes Effective from 29 July 2026"},{"id":"LPTV2026.041","category":"Administrative penalties","status":"official_transport_malta","question":"Who is liable to pay a staggered garaging or parking fine linked to a defaulting vehicle?","question_it":"Chi è tenuto a pagare una multa progressiva per garaging o parcheggio collegata a un veicolo in violazione?","answers":["The passenger","The Operator Licence holder associated with the vehicle registration number","The fuel station","The vehicle manufacturer"],"answers_it":["Il passeggero","Il titolare della licenza operatore associato alla targa del veicolo","Il distributore di carburante","Il costruttore del veicolo"],"correct":[1],"explanation":"The fine is payable by the Operator Licence holder associated with the defaulting vehicle's registration number.","explanation_it":"La multa è a carico del titolare della licenza operatore associato alla targa del veicolo in violazione.","source":"Transport Malta - Changes Effective from 29 July 2026"},{"id":"LPTV2026.042","category":"Administrative penalties","status":"official_transport_malta","question":"Is a €500 penalty automatically imposed for every parking infringement under the revised system?","question_it":"Nel sistema revisionato viene applicata automaticamente una multa di €500 per ogni violazione di parcheggio?","answers":["Yes","No, a staggered system applies","Only during daytime","Only to SOV vehicles"],"answers_it":["Sì","No, si applica un sistema progressivo","Solo di giorno","Solo ai veicoli SOV"],"correct":[1],"explanation":"The revised system uses staggered penalties rather than automatically imposing €500 for every infringement.","explanation_it":"Il sistema revisionato usa sanzioni progressive invece di applicare automaticamente €500 per ogni violazione.","source":"Transport Malta - Changes Effective from 29 July 2026"},{"id":"LPTV2026.043","category":"Operator responsibilities","status":"official_transport_malta","question":"What must operators ensure about their Operator Licence?","question_it":"Cosa devono garantire gli operatori riguardo alla propria licenza operatore?","answers":["That it remains valid","That it is kept only in the vehicle","That passengers sign it","That it is renewed every month"],"answers_it":["Che rimanga valida","Che sia conservata solo nel veicolo","Che venga firmata dai passeggeri","Che venga rinnovata ogni mese"],"correct":[0],"explanation":"Operators must ensure their Operator Licence remains valid.","explanation_it":"Gli operatori devono garantire che la licenza operatore rimanga valida.","source":"Transport Malta - Changes Effective from 29 July 2026"},{"id":"LPTV2026.044","category":"Operator responsibilities","status":"official_transport_malta","question":"What must operators ensure about authorised vehicles?","question_it":"Cosa devono garantire gli operatori riguardo ai veicoli autorizzati?","answers":["They have valid documentation","They are always parked on the road","They are all the same colour","They are driven only at night"],"answers_it":["Che abbiano documentazione valida","Che siano sempre parcheggiati su strada","Che siano tutti dello stesso colore","Che siano guidati solo di notte"],"correct":[0],"explanation":"Vehicles operating under the licence must be properly authorised and have valid documentation.","explanation_it":"I veicoli che operano sotto la licenza devono essere correttamente autorizzati e avere documentazione valida.","source":"Transport Malta - Changes Effective from 29 July 2026"},{"id":"LPTV2026.045","category":"Special Occasion Vehicles","status":"official_transport_malta","question":"Which of the following may be an eligible pre-booked SOV service? Select 3 answers.","question_it":"Quali dei seguenti possono essere servizi SOV prenotati idonei? Seleziona 3 risposte.","answers":["Wedding transport","Airport transfer","Sightseeing service","Accepting immediate street hails","Receiving bookings through a ride-hailing platform"],"answers_it":["Trasporto per matrimoni","Trasferimento aeroportuale","Servizio turistico","Accettare clienti fermati per strada","Ricevere prenotazioni tramite piattaforma ride-hailing"],"correct":[0,1,2],"explanation":"Eligible SOV services may include weddings, airport transfers and sightseeing, provided they are pre-booked.","explanation_it":"I servizi SOV idonei possono includere matrimoni, trasferimenti aeroportuali e sightseeing, purché prenotati.","source":"Transport Malta - Changes Effective from 29 July 2026"},{"id":"LPTV2026.046","category":"Parking","status":"official_transport_malta","question":"What must the official parking clock show?","question_it":"Cosa deve indicare l'orologio ufficiale di parcheggio?","answers":["The time when the vehicle was parked","The driver's finishing time","The next booking time","The vehicle's service date"],"answers_it":["L'ora in cui il veicolo è stato parcheggiato","L'ora di fine turno del conducente","L'orario della prossima prenotazione","La data del tagliando"],"correct":[0],"explanation":"The clock must be correctly set to show the time when the vehicle was parked.","explanation_it":"L'orologio deve essere impostato correttamente per indicare l'ora in cui il veicolo è stato parcheggiato.","source":"Transport Malta - Changes Effective from 29 July 2026"},{"id":"LPOINTS1.62","category":"Road signs and junctions","status":"official_transport_malta","question":"Should you observe a STOP sign even when no other vehicles are coming?","question_it":"Devi rispettare un segnale STOP anche quando non arrivano altri veicoli?","answers":["No","Sometimes","Yes","Only at night"],"answers_it":["No","A volte","Sì","Solo di notte"],"correct":[2],"explanation":"A STOP sign requires a complete stop even when the road appears clear.","explanation_it":"Il segnale STOP impone un arresto completo anche quando la strada sembra libera.","source":"Transport Malta L-Points Study Material English 2018"},{"id":"LPOINTS1.74","category":"Horn","status":"official_transport_malta","question":"What does a 'Do not use your horn' sign mean?","question_it":"Cosa significa il segnale 'Non usare il clacson'?","answers":["Use your horn","No marching bands","Do not use your horn","Hospital parking"],"answers_it":["Usa il clacson","Divieto di bande musicali","Non usare il clacson","Parcheggio ospedale"],"correct":[2],"explanation":"The sign prohibits the use of the horn in that area.","explanation_it":"Il segnale vieta l'uso del clacson in quella zona.","source":"Transport Malta L-Points Study Material English 2018"},{"id":"LPOINTS1.79","category":"Road signs and junctions","status":"official_transport_malta","question":"If a STOP or GIVE WAY sign has no road markings, what should you do?","question_it":"Se un segnale STOP o DARE PRECEDENZA non ha segnaletica orizzontale, cosa devi fare?","answers":["Ignore the sign","Stop or give way at the safest point where you can see clearly","Sound your horn and continue","Stop five metres after the junction"],"answers_it":["Ignorare il segnale","Fermarti o dare precedenza nel punto più sicuro da cui puoi vedere chiaramente","Suonare e proseguire","Fermarti cinque metri dopo l'incrocio"],"correct":[1],"explanation":"You must obey the sign and position the vehicle where you can see and proceed safely.","explanation_it":"Devi rispettare il segnale e posizionare il veicolo dove puoi vedere e procedere in sicurezza.","source":"Transport Malta L-Points Study Material English 2018"},{"id":"LPOINTS1.92","category":"Traffic calming","status":"official_transport_malta","question":"Why are road humps and chicanes installed?","question_it":"Perché vengono installati dossi e chicane?","answers":["To check your suspension","To increase traffic speed","To reduce traffic speed","To create parking spaces"],"answers_it":["Per controllare le sospensioni","Per aumentare la velocità","Per ridurre la velocità del traffico","Per creare parcheggi"],"correct":[2],"explanation":"Road humps and chicanes are traffic-calming measures intended to reduce speed.","explanation_it":"Dossi e chicane sono misure di moderazione del traffico destinate a ridurre la velocità.","source":"Transport Malta L-Points Study Material English 2018"},{"id":"LPOINTS1.93","category":"Road signs and junctions","status":"official_transport_malta","question":"You approach an intersection with a STOP sign. Where should you stop?","question_it":"Ti avvicini a un incrocio con un segnale STOP. Dove devi fermarti?","answers":["Five metres after the intersection","Five metres before the intersection","Before the road marking at the end of the road","In the middle of the junction"],"answers_it":["Cinque metri dopo l'incrocio","Cinque metri prima dell'incrocio","Prima della linea stradale alla fine della strada","Al centro dell'incrocio"],"correct":[2],"explanation":"Stop before the stop line or road marking at the end of the road.","explanation_it":"Fermati prima della linea di arresto o della segnaletica alla fine della strada.","source":"Transport Malta L-Points Study Material English 2018"},{"id":"LPOINTS1.97","category":"Lane changing","status":"official_transport_malta","question":"What should you do before changing lanes?","question_it":"Cosa devi fare prima di cambiare corsia?","answers":["Signal for two seconds and move quickly","Speed up first","Check mirrors, signal and look over your shoulder","Sound the horn"],"answers_it":["Segnalare per due secondi e spostarti rapidamente","Accelerare prima","Controllare gli specchi, segnalare e guardare sopra la spalla","Suonare il clacson"],"correct":[2],"explanation":"Use mirrors and signals and check the blind spot over your shoulder.","explanation_it":"Usa specchi e indicatori e controlla l'angolo cieco guardando sopra la spalla.","source":"Transport Malta L-Points Study Material English 2018"},{"id":"LPOINTS1.98","category":"Safe loading","status":"official_transport_malta","question":"Who is responsible for ensuring that a vehicle is not overloaded?","question_it":"Chi è responsabile di assicurarsi che un veicolo non sia sovraccarico?","answers":["The passengers","The driver","The vehicle owner only","The insurance company"],"answers_it":["I passeggeri","Il conducente","Solo il proprietario","L'assicurazione"],"correct":[1],"explanation":"The driver is responsible for ensuring the vehicle is not overloaded.","explanation_it":"Il conducente è responsabile di assicurarsi che il veicolo non sia sovraccarico.","source":"Transport Malta L-Points Study Material English 2018"},{"id":"LPOINTS1.99","category":"Signals","status":"official_transport_malta","question":"When is signalling required?","question_it":"Quando è necessario segnalare?","answers":["Not always when turning","Before turning or changing lane","Only during the day","Only when another vehicle is close"],"answers_it":["Non sempre quando si svolta","Prima di svoltare o cambiare corsia","Solo di giorno","Solo quando un altro veicolo è vicino"],"correct":[1],"explanation":"Signal in good time before turning or changing lanes.","explanation_it":"Segnala per tempo prima di svoltare o cambiare corsia.","source":"Transport Malta L-Points Study Material English 2018"},{"id":"LPOINTS1.100","category":"Vehicle faults","status":"official_transport_malta","question":"What can cause heavy steering?","question_it":"Cosa può causare uno sterzo pesante?","answers":["Over-inflated tyres","Under-inflated tyres","Driving in rain","Full fuel tank"],"answers_it":["Pneumatici troppo gonfi","Pneumatici sgonfi","Guidare sotto la pioggia","Serbatoio pieno"],"correct":[1],"explanation":"Under-inflated tyres increase steering effort and affect handling.","explanation_it":"Pneumatici sgonfi aumentano lo sforzo sullo sterzo e peggiorano la maneggevolezza.","source":"Transport Malta L-Points Study Material English 2018"},{"id":"LPOINTS1.103","category":"Box junctions","status":"official_transport_malta","question":"When may you enter a box junction?","question_it":"Quando puoi entrare in un box junction?","answers":["When turning left","When your exit is clear","When fewer than two vehicles are ahead","Whenever the light is green"],"answers_it":["Quando giri a sinistra","Quando la tua uscita è libera","Quando ci sono meno di due veicoli davanti","Ogni volta che il semaforo è verde"],"correct":[1],"explanation":"Do not enter a box junction unless your exit is clear.","explanation_it":"Non entrare in un box junction se la tua uscita non è libera.","source":"Transport Malta L-Points Study Material English 2018"},{"id":"LPOINTS1.106","category":"Overtaking","status":"official_transport_malta","question":"Where should you avoid overtaking?","question_it":"Dove devi evitare il sorpasso?","answers":["On a road with a 50 km/h limit","On a one-way street","On the approach to a bend","On a dual carriageway"],"answers_it":["Su una strada con limite di 50 km/h","Su una strada a senso unico","Avvicinandoti a una curva","Su una strada a doppia carreggiata"],"correct":[2],"explanation":"Avoid overtaking when approaching a bend because your view is restricted.","explanation_it":"Evita di sorpassare avvicinandoti a una curva perché la visuale è limitata.","source":"Transport Malta L-Points Study Material English 2018"},{"id":"LPOINTS1.107","category":"Attitude","status":"official_transport_malta","question":"What should you do if another driver overtakes you?","question_it":"Cosa devi fare se un altro conducente ti sorpassa?","answers":["Keep calm and continue driving","Overtake them back","Shout at them","Tailgate them"],"answers_it":["Restare calmo e continuare a guidare","Risuperarlo","Gridargli contro","Stargli attaccato"],"correct":[0],"explanation":"Remain calm and do not retaliate or accelerate.","explanation_it":"Resta calmo e non reagire né accelerare.","source":"Transport Malta L-Points Study Material English 2018"},{"id":"LPOINTS1.108","category":"Horn","status":"official_transport_malta","question":"What is the main purpose of the horn?","question_it":"Qual è lo scopo principale del clacson?","answers":["To scold someone","To warn other road users of your presence","To greet someone you know","To make traffic move faster"],"answers_it":["Per rimproverare qualcuno","Per avvertire gli altri utenti della tua presenza","Per salutare una persona conosciuta","Per far muovere più velocemente il traffico"],"correct":[1],"explanation":"The horn is a warning device used to alert others to your presence.","explanation_it":"Il clacson è un dispositivo di avvertimento usato per segnalare agli altri la tua presenza.","source":"Transport Malta L-Points Study Material English 2018"},{"id":"LPOINTS1.110","category":"Fatigue","status":"official_transport_malta","question":"What is microsleep?","question_it":"Cos'è un microsleep?","answers":["A temporary episode of sleep or drowsiness","Sleeping in the rear seat","A short sleep in a hotel","A planned rest break"],"answers_it":["Un breve episodio di sonno o sonnolenza","Dormire sul sedile posteriore","Un breve sonno in hotel","Una pausa programmata"],"correct":[0],"explanation":"Microsleep is a very short, involuntary episode of sleep or loss of attention.","explanation_it":"Il microsleep è un brevissimo episodio involontario di sonno o perdita di attenzione.","source":"Transport Malta L-Points Study Material English 2018"},{"id":"LPOINTS1.111","category":"Fatigue","status":"official_transport_malta","question":"What should you do if you are too tired to drive?","question_it":"Cosa devi fare se sei troppo stanco per guidare?","answers":["Use public transport or get a lift","Drive faster to get home","Drink strong coffee and drive immediately","Open the window and continue"],"answers_it":["Usare il trasporto pubblico o farti accompagnare","Guidare più velocemente","Bere caffè forte e partire subito","Aprire il finestrino e continuare"],"correct":[0],"explanation":"Do not drive when overtired; use another form of transport.","explanation_it":"Non guidare quando sei troppo stanco; usa un altro mezzo di trasporto.","source":"Transport Malta L-Points Study Material English 2018"},{"id":"LPOINTS1.114","category":"Defensive driving","status":"official_transport_malta","question":"What is defensive driving?","question_it":"Cos'è la guida difensiva?","answers":["Driving safely despite conditions and the actions of others","Always giving way","Using stop signs and zebra crossings","Driving slowly at all times"],"answers_it":["Guidare in sicurezza nonostante le condizioni e le azioni degli altri","Dare sempre precedenza","Usare STOP e attraversamenti","Guidare sempre lentamente"],"correct":[0],"explanation":"Defensive driving means anticipating hazards and protecting yourself from others' mistakes.","explanation_it":"La guida difensiva significa anticipare i pericoli e proteggersi dagli errori degli altri.","source":"Transport Malta L-Points Study Material English 2018"},{"id":"LPOINTS1.115","category":"Distractions","status":"official_transport_malta","question":"Should a driver avoid distractions and concentrate on the road?","question_it":"Il conducente deve evitare le distrazioni e concentrarsi sulla strada?","answers":["Yes","Only when stressed","No","Only on motorways"],"answers_it":["Sì","Solo quando è stressato","No","Solo sulle autostrade"],"correct":[0],"explanation":"A driver should avoid all distractions and maintain full attention.","explanation_it":"Il conducente deve evitare tutte le distrazioni e mantenere piena attenzione.","source":"Transport Malta L-Points Study Material English 2018"},{"id":"LPOINTS1.118","category":"Weather","status":"official_transport_malta","question":"How should you drive in rough weather or dangerous conditions?","question_it":"Come devi guidare con maltempo o condizioni pericolose?","answers":["More cautiously","Faster to arrive sooner","Avoid main roads only","Use the horn continuously"],"answers_it":["Con maggiore prudenza","Più velocemente per arrivare prima","Evitare solo le strade principali","Usare continuamente il clacson"],"correct":[0],"explanation":"Reduce speed, increase distance and drive more cautiously.","explanation_it":"Riduci la velocità, aumenta la distanza e guida con maggiore prudenza.","source":"Transport Malta L-Points Study Material English 2018"},{"id":"LPOINTS1.123","category":"Floods","status":"official_transport_malta","question":"What should you do when the road is heavily flooded?","question_it":"Cosa devi fare quando la strada è fortemente allagata?","answers":["Continue normally","Plan ahead and avoid the flooded area","Speed through the water","Follow the vehicle ahead closely"],"answers_it":["Continuare normalmente","Pianificare in anticipo ed evitare l'area allagata","Attraversare velocemente l'acqua","Seguire da vicino il veicolo davanti"],"correct":[1],"explanation":"Avoid heavily flooded areas where possible because water depth and hazards may be unknown.","explanation_it":"Evita le aree fortemente allagate quando possibile perché profondità e pericoli possono essere sconosciuti.","source":"Transport Malta L-Points Study Material English 2018"},{"id":"LPOINTS1.124","category":"Accidents","status":"official_transport_malta","question":"If someone is injured in an accident, what should the driver do?","question_it":"Se qualcuno rimane ferito in un incidente, cosa deve fare il conducente?","answers":["Leave immediately","Offer a cigarette","Call 112 and provide assistance","Call 911"],"answers_it":["Andarsene immediatamente","Offrire una sigaretta","Chiamare il 112 e prestare assistenza","Chiamare il 911"],"correct":[2],"explanation":"Call the emergency services on 112 and provide reasonable assistance.","explanation_it":"Chiama i servizi di emergenza al 112 e presta ragionevole assistenza.","source":"Transport Malta L-Points Study Material English 2018"},{"id":"LPOINTS1.134","category":"Parking","status":"official_transport_malta","question":"Should you signal other drivers that you intend to park?","question_it":"Devi segnalare agli altri conducenti che intendi parcheggiare?","answers":["Always","Sometimes","Never","Only at night"],"answers_it":["Sempre","A volte","Mai","Solo di notte"],"correct":[0],"explanation":"Signal clearly and in good time before parking.","explanation_it":"Segnala chiaramente e per tempo prima di parcheggiare.","source":"Transport Malta L-Points Study Material English 2018"},{"id":"LPOINTS1.171","category":"Tunnels","status":"official_transport_malta","question":"How should you drive through a tunnel?","question_it":"Come devi guidare in una galleria?","answers":["Speed and stay in one lane","Switch on your lights and stay in the same lane","Change lanes whenever possible","Use hazard lights throughout"],"answers_it":["Accelerare e restare in corsia","Accendere le luci e restare nella stessa corsia","Cambiare corsia quando possibile","Usare le quattro frecce per tutta la galleria"],"correct":[1],"explanation":"Use your lights and remain in lane throughout the tunnel unless directed otherwise.","explanation_it":"Accendi le luci e resta nella stessa corsia per tutta la galleria, salvo diversa indicazione.","source":"Transport Malta L-Points Study Material English 2018"},{"id":"LPOINTS1.172","category":"Large vehicles","status":"official_transport_malta","question":"What should you do when a long vehicle is turning around a roundabout?","question_it":"Cosa devi fare quando un veicolo lungo sta svoltando in una rotatoria?","answers":["Give it plenty of room","Overtake it","Sound your horn","Drive alongside it"],"answers_it":["Lasciargli molto spazio","Sorpassarlo","Suonare il clacson","Affiancarlo"],"correct":[0],"explanation":"Long vehicles need extra space and may use more than one lane.","explanation_it":"I veicoli lunghi hanno bisogno di più spazio e possono occupare più di una corsia.","source":"Transport Malta L-Points Study Material English 2018"},{"id":"LPOINTS1.175","category":"Tyres","status":"official_transport_malta","question":"How often should tyre pressure be checked at least?","question_it":"Almeno con quale frequenza deve essere controllata la pressione degli pneumatici?","answers":["Every week","Every day","Every month","Once a year"],"answers_it":["Ogni settimana","Ogni giorno","Ogni mese","Una volta all'anno"],"correct":[0],"explanation":"The official study material recommends checking tyre pressure at least weekly.","explanation_it":"Il materiale ufficiale raccomanda di controllare la pressione almeno ogni settimana.","source":"Transport Malta L-Points Study Material English 2018"},{"id":"LPOINTS1.176","category":"Vehicle lights","status":"official_transport_malta","question":"What colour should hazard warning lights be?","question_it":"Di che colore devono essere le luci di emergenza?","answers":["Red","Yellow","Amber","White"],"answers_it":["Rosse","Gialle","Ambra","Bianche"],"correct":[2],"explanation":"Hazard warning indicators flash amber.","explanation_it":"Gli indicatori di emergenza lampeggiano in colore ambra.","source":"Transport Malta L-Points Study Material English 2018"},{"id":"LPOINTS1.182","category":"Parking","status":"official_transport_malta","question":"How many metres should be left clear when parking near a corner or traffic junction?","question_it":"Quanti metri devono essere lasciati liberi parcheggiando vicino a un angolo o incrocio?","answers":["5 metres","4 metres","7 metres","12 metres"],"answers_it":["5 metri","4 metri","7 metri","12 metri"],"correct":[0],"explanation":"Leave at least five metres clear at a corner or traffic junction.","explanation_it":"Lascia almeno cinque metri liberi in prossimità di un angolo o incrocio.","source":"Transport Malta L-Points Study Material English 2018"},{"id":"LPOINTS1.183","category":"Parking","status":"official_transport_malta","question":"How many metres should be left clear on each side of a bus stop or fare stage?","question_it":"Quanti metri devono essere lasciati liberi su ciascun lato di una fermata autobus o fare stage?","answers":["12 metres","15 metres","7 metres","5 metres"],"answers_it":["12 metri","15 metri","7 metri","5 metri"],"correct":[0],"explanation":"Leave twelve metres clear on each side of a bus stop or fare stage.","explanation_it":"Lascia dodici metri liberi su ciascun lato di una fermata autobus o fare stage.","source":"Transport Malta L-Points Study Material English 2018"},{"id":"LPOINTS1.184","category":"Horn","status":"official_transport_malta","question":"Near which place is the use of horns usually restricted?","question_it":"Vicino a quale luogo l'uso del clacson è generalmente limitato?","answers":["Art museums","Historical sites","Hospitals","Shopping centres"],"answers_it":["Musei d'arte","Siti storici","Ospedali","Centri commerciali"],"correct":[2],"explanation":"Horn use is commonly restricted near hospitals to avoid unnecessary noise.","explanation_it":"L'uso del clacson è comunemente limitato vicino agli ospedali per evitare rumore inutile.","source":"Transport Malta L-Points Study Material English 2018"}];